    r.CFOEstimateAvailability = "available";
    r.CFOValueStatus = "MEASURED";
else
    r.CFOEstimateAvailability = "missing";
    r.CFOValueStatus = "NOT_AVAILABLE";
end
r.CollisionFlag = double(logical(sixgr.util.structGet(ra, "CollisionDetected", false)));
r.FalseAlarm = preambleDetected && isfinite(r.DetectedPreambleIndex) && isfinite(r.PreambleIndex) && ...
    round(double(r.DetectedPreambleIndex)) ~= round(double(r.PreambleIndex));
r.FalseAlarmFlag = double(logical(r.FalseAlarm));
r.MissedDetection = ~preambleDetected;
% Msg1 is preamble detection, not a CRC-protected transport block. Overall
% procedure acceptance belongs in StrictOk/RACompleted; the actual Msg2,
% Msg3, Msg4 and SetupComplete CRCs remain in their named receiver fields.
r.CRCPass = NaN;
r.CRCApplicable = false;
r.CRCOutcome = "not_applicable";
r.DetectionSuccess = preambleDetected;
r.DetectionAttempted = true;
r.DetectionUsable = preambleDetected && isfinite(double(r.DetectionMetric));
r.MeasurementAttempted = true;
r.MeasurementUsable = strictOk;
r.ReceiverUsable = strictOk;
r.DecodeAttempted = true;
r.DecodeUsable = strictOk;
r.StrictReceiverEvidenceOk = strictOk;
r.StrictOk = strictOk;
if strictOk
    r.Status = "PASS";
    r.RAStage = "RA_SUCCESS";
    if logical(sixgr.util.structGet(ra, "RequireRRCSetupComplete", false))
        r.Notes = "strict_initial_access_waveform_chain_completed_msg1_msg2_msg3_msg4_rrc_setup_complete";
    else
        r.Notes = "strict_four_step_ra_waveform_chain_completed_msg1_msg2_msg3_msg4";
    end
else
    r.Status = "FAIL";
    r.RAStage = string(sixgr.util.structGet(ra, "ObservedFailureStage", ""));
    r.Notes = "strict_four_step_ra_waveform_chain_failed:" + string(sixgr.util.structGet(ra, "FailureReason", ""));
end
r.RAFailureReason = string(sixgr.util.structGet(ra, "FailureReason", ""));
r.TruthStatus = "real_lls_evidence";
r.SourceClassification = "active_integrated";
if logical(sixgr.util.structGet(ra, "RequireRRCSetupComplete", false))
    r.RuntimeMaterializationStatus = "active_integrated_initial_access_waveform_msg1_msg2_msg3_msg4_rrc_setup_complete";
else
    r.RuntimeMaterializationStatus = "active_integrated_four_step_ra_waveform_msg1_msg2_msg3_msg4";
end
r.ControlGatingEffect = "random_access_gate_full_four_step_ra";
r.RuntimeStateConsumer = "CoupledTruthRuntime.applyPRACHTrial";
r.RuntimeConsumer = "CoupledTruthRuntime.applyPRACHTrial";
r.RuntimeEvidenceSource = "sixgr.phy.ra.runFourStepRA";
r.FullRAEvidenceSource = "sixgr.phy.ra.runFourStepRA";
r.FullRAArtifactRunFolder = "control/csv";
end

function T = localBuildFourStepRACorrelationTraceTable(ra, prachRow, cfg, snr_dB, trialIdx)
trace = sixgr.util.structGet(ra, "Msg1DetectionTrace", struct());
lags = double(sixgr.util.structGet(trace, "LagSamples", zeros(0, 1)));
corrAbs = double(sixgr.util.structGet(trace, "CorrelationAbs", zeros(0, 1)));
lags = lags(:);
corrAbs = corrAbs(:);
n = min(numel(lags), numel(corrAbs));
if n < 1
    T = table();
    return;
end
lags = lags(1:n);
corrAbs = corrAbs(1:n);
valid = isfinite(lags) & isfinite(corrAbs);
lags = lags(valid);
corrAbs = corrAbs(valid);
n = numel(lags);
if n < 1
    T = table();
    return;
end
msg1Tx = sixgr.util.structGet(ra, "Msg1Tx", struct());
sampleRateHz = double(sixgr.util.structGet(msg1Tx, "SampleRate_Hz", ...
    sixgr.util.structGet(msg1Tx, "PRACHRuntimeConfig.SampleRate_Hz", NaN)));
if ~(isfinite(sampleRateHz) && sampleRateHz > 0)
    error("sixgr:truth:MissingFourStepRACorrelationSampleRate", ...
        "Runtime Msg1 correlation trace requires its actual waveform sample rate.");
end
threshold = double(sixgr.util.structGet(trace, "Threshold", ...
    sixgr.util.structGet(ra, "PreambleDetectionThreshold", NaN)));
noiseFloor = double(sixgr.util.structGet(trace, "NoiseFloor", ...
    sixgr.util.structGet(ra, "Msg1PDPAverageNoiseFloor", NaN)));
peakLag = double(sixgr.util.structGet(trace, "PeakLagSamples", ...
    sixgr.util.structGet(ra, "Msg1DetectorPeakLagSamples", NaN)));
detected = logical(sixgr.util.structGet(ra, "PreambleDetected", ...
    sixgr.util.structGet(prachRow, "DetectionSuccess", false)));
falseAlarm = logical(sixgr.util.structGet(ra, "FalseAlarm", false));
missed = ~detected && ~falseAlarm;
detectionResult = repmat("missed_detection", n, 1);
if detected
    detectionResult(:) = "detected";
elseif falseAlarm
    detectionResult(:) = "false_alarm";
end
seed = round(double(sixgr.util.structGet(cfg, "run.seed", ...
    sixgr.util.structGet(cfg, "run_control.seed", 1)))) + round(double(trialIdx)) - 1;
T = table( ...
    repmat(double(trialIdx), n, 1), ...
    repmat(double(sixgr.util.structGet(ra, "PreambleIndexDetected", NaN)), n, 1), ...
    repmat(double(sixgr.util.structGet(prachRow, "PRACHRootSequenceIndex", NaN)), n, 1), ...
    repmat(string(sixgr.util.structGet(prachRow, "PRACHRestrictedSetType", "")), n, 1), ...
    repmat(double(sixgr.util.structGet(prachRow, "PRACHNCS", NaN)), n, 1), ...
    repmat(double(sixgr.util.structGet(prachRow, "PRACHZeroCorrelationZone", NaN)), n, 1), ...
    lags, lags ./ sampleRateHz .* 1e6, corrAbs, ...
    repmat(threshold, n, 1), repmat(noiseFloor, n, 1), ...
    repmat(peakLag, n, 1), ...
    repmat(sixgr.truth.receivedRARTimingOnTraceClock(ra, sampleRateHz), n, 1), ...
    detectionResult, repmat(falseAlarm, n, 1), repmat(missed, n, 1), ...
    repmat(double(snr_dB), n, 1), ...
    repmat(double(sixgr.util.structGet(ra, "PRACHFrequencyEstimate_Hz", 0)), n, 1), ...
    repmat(double(seed), n, 1), repmat("real_lls_evidence", n, 1), ...
    'VariableNames', {'trial_id','preamble_index','root_sequence_index', ...
    'restricted_set_type','n_cs','zero_correlation_zone_config', ...
    'lag_samples','lag_us','correlation_abs','threshold','noise_floor', ...
    'peak_lag_samples','timing_advance_samples','detection_result', ...
    'false_alarm','missed_detection','snr_db','cfo_hz','seed','truth_status'});
end

function tables = localEmptyRAEvidenceTables()
names = localRAEvidenceTableNames();
tables = struct();
for i = 1:numel(names)
    name = names(i);
    if ismember(name, ["ra_negative_trials", "ra_collision_trials"])
        tables.(char(name)) = ...
            sixgr.phy.ra.emptyOptionalEvidenceTable(name);
    else
        tables.(char(name)) = table();
    end
end
end

function out = localAppendRAEvidenceTables(out, in)
if nargin < 1 || ~isstruct(out) || isempty(fieldnames(out))
    out = localEmptyRAEvidenceTables();
end
if nargin < 2 || ~isstruct(in)
    return;
end
names = unique([localRAEvidenceTableNames(), string(fieldnames(in)).'], "stable");
for i = 1:numel(names)
    f = char(names(i));
    if ~isfield(out, f)
        out.(f) = table();
    end
    if isfield(in, f) && istable(in.(f))
        if isempty(out.(f)) && width(out.(f)) == 0 && width(in.(f)) > 0
            % Preserve the producer-owned schema even when the optional
            % campaign emitted no runtime rows.
            out.(f) = in.(f)(zeros(0, 1), :);
        end
        if ~isempty(in.(f))
            out.(f) = localAppendCompatTable(out.(f), in.(f));
        end
    end
end
end

function localWriteRAEvidenceTables(rootRunFolder, tables)
if strlength(string(rootRunFolder)) == 0 || ~isstruct(tables)
    return;
end
layout = sixgr.report.resultLayout(rootRunFolder);
names = localRAEvidenceTableNames();
for i = 1:numel(names)
    f = char(names(i));
    if isfield(tables, f) && istable(tables.(f)) && ...
            (~isempty(tables.(f)) || width(tables.(f)) > 0)
        artifactPath = fullfile(layout.ControlCSVDir, string(f) + ".csv");
        if ~isempty(tables.(f)) || exist(artifactPath, "file") ~= 2
            sixgr.util.csvWriteTable(artifactPath, tables.(f), ...
                "PreserveSchema", true);
        end
    end
end
if isfield(tables, "msg4_contention_resolution") && istable(tables.msg4_contention_resolution) && ...
        ~isempty(tables.msg4_contention_resolution)
    sixgr.util.csvWriteTable(fullfile(layout.ControlCSVDir, "msg4_trials.csv"), ...
        tables.msg4_contention_resolution);
end
end

function names = localRAEvidenceTableNames()
names = ["ra_attempts","ra_state_transitions","msg1_prach_detection", ...
    "ra_retry_events","ra_power_reference_decisions", ...
    "rar_monitoring_observations","rar_monitoring_candidates","rar_monitoring_decoded_fields", ...
    "msg2_rar_trials","msg2_pdcch_candidates","msg2_dci_fields","msg4_dci_fields","msg3_pusch_trials", ...
    "msg4_contention_resolution","rrc_connection_events","rrc_setup_complete", ...
    "ra_timer_events","ra_negative_trials", ...
    "ra_collision_trials","ra_oracle_guard","ra_runtime_stage_waveforms"];
end

function [T,updatedRuntimeChannelState,observedRET,allocatedRECoordinates] = localCollectPDCCHTrials( ...
        cfg,snr_dB,nTrials,grantContext,initialRuntimeChannelState,occupiedRECoordinates)
nTrials = max(1, round(double(nTrials)));
rows = repmat(localMakeLinkTrialRow(cfg, "DL", snr_dB, 1), nTrials, 1);
if nargin < 4 || ~isstruct(grantContext)
    grantContext = struct();
end
if nargin < 5 || ~isstruct(initialRuntimeChannelState)
    initialRuntimeChannelState = struct();
end
updatedRuntimeChannelState = initialRuntimeChannelState;
observedRET = table();
allocatedRECoordinates = zeros(0,2);
reserveControlResources = nargin >= 6;
if reserveControlResources && nTrials ~= 1
    error("sixgr:truth:PDCCHReservationTrialScope", ...
        "A shared control-slot reservation must execute one scheduled DCI at a time.");
end
dciBitsSeed = int8([]);
if isstruct(sixgr.util.structGet(grantContext, "DCI", struct()))
    dciBitsSeed = int8(sixgr.util.structGet(sixgr.util.structGet(grantContext, "DCI", struct()), "Bits", int8([])));
end
for k = 1:nTrials
    r = localMakeLinkTrialRow(cfg, "DL", snr_dB, k);
    r.Status = "FAIL";
    % A generation/propagation exception is not a measured CRC failure.
    r.CRCPass = NaN;
    r.CRCApplicable = false;
    try
        cfgTrial = localResolvePDCCHTrialConfig(cfg, snr_dB, k, nTrials, grantContext);
        grantRNTI = double(sixgr.util.structGet(grantContext, "RNTI", ...
            sixgr.util.structGet(cfgTrial, "phy.pdsch.RNTI", ...
            sixgr.util.structGet(cfgTrial, "phy.pdcch.rnti", NaN))));
        txArgs = {};
        if isfinite(grantRNTI)
            txArgs = [txArgs {"RNTI", grantRNTI}]; %#ok<AGROW>
        end
        if ~isempty(dciBitsSeed)
            txArgs = [txArgs {"DCIBits", dciBitsSeed}]; %#ok<AGROW>
        elseif ~isempty(fieldnames(grantContext))
            error('sixgr:truth:MissingScheduledPDCCHPayload', ...
                'A scheduler DCI must use the actual finalized grant payload.');
        else
            payloadBits=sixgr.util.structGet(cfgTrial,'phy.pdcch.configuredPayloadBits', ...
                sixgr.util.structGet(cfgTrial,'phy.pdcch.dciPayloadBits',[]));
            validateattributes(payloadBits,{'numeric'},{'scalar','finite','integer','positive'});
            txArgs = [txArgs {"K", payloadBits}]; %#ok<AGROW>
        end
        if reserveControlResources
            txArgs = [txArgs {"ReservedRECoordinates", occupiedRECoordinates}]; %#ok<AGROW>
        end
        preparedPDCCH = sixgr.link.preparePDCCHTransmission(cfgTrial,txArgs{:});
        tx = preparedPDCCH.Tx;
        txInfo = preparedPDCCH.TxInfo;
        allocatedRECoordinates = txInfo.AllocatedRECoordinates;
        observedSlot0 = double(sixgr.util.structGet(cfgTrial, ...
            "lls6g.runtime.AbsoluteSlotIndex0", tx.Carrier.NSlot));
        pdcchTx = struct("Carrier", tx.Carrier, "Grid", tx.Grid, ...
            "PDCCHIndices", tx.PDCCHInd, "DMRSIndices", tx.DMRSInd);
        pdcchRET = sixgr.truth.buildObservedREAllocation(pdcchTx, ...
            "Direction", "DL", "Channel", "PDCCH", ...
            "AbsoluteSlot", observedSlot0, ...
            "CellID", double(tx.Carrier.NCellID), ...
            "UEID", double(sixgr.util.structGet(grantContext, "UEIndex", NaN)), ...
            "AllocationID", "pdcch_slot_" + string(observedSlot0));
        [rxWave,nVar,replay,updatedRuntimeChannelState] = ...
            localApplyPDCCHChannelAndNoise(preparedPDCCH,snr_dB,updatedRuntimeChannelState);
        observedRET = localAppendCompatTable(observedRET,pdcchRET);
        runtimeChannelUsed = logical(sixgr.util.structGet( ...
            replay,"RuntimeChannelStateUsed",false));
        fadingChannelApplied = logical(sixgr.util.structGet( ...
            replay,"ChannelFadingApplied",false));
        if runtimeChannelUsed && fadingChannelApplied
            % A retained fading channel owns its absolute execution clock.
            % Its replay origin must therefore be present and agree with
            % the scheduled PDCCH occasion checked by receive completion.
            origin = double(sixgr.util.structGet( ...
                replay,"RuntimeChannelStartSample",NaN));
            if ~isfinite(origin)
                error('sixgr:truth:PDCCHRuntimeChannelOriginMissing', ...
                    'A retained PDCCH fading execution must expose its absolute sample origin.');
            end
        else
            % Identity/AWGN/RF replay metadata can contain a local zero
            % origin even though no fading channel clock executed.
            % The actual scheduled producer clock is authoritative here.
            origin = preparedPDCCH.RuntimeStartSample;
            if ~isfinite(origin)
                origin = 0; % Standalone capture without a scheduled absolute origin.
            end
        end
        observation = sixgr.phy.waveform.WaveformObservationBuffer( ...
            origin,origin+size(rxWave,1),preparedPDCCH.SampleRateHz,size(rxWave,2));
        observation.append(sixgr.phy.waveform.WaveformChunk(rxWave,origin),preparedPDCCH.SampleRateHz);
        r = localCompletePDCCHTrial(preparedPDCCH,observation,grantContext,snr_dB,k,nVar,replay);
    catch ME
        r.Crash = true;
        r.Status = "CRASH";
        r.FailureReason = string(ME.identifier);
        r.Notes = string(ME.message);
        if strcmp(ME.identifier, 'sixgr:phy:pdcch:NoFreeCandidate')
            r.Crash = false;
            r.Status = "BLOCKED";
            r.CRCPass = NaN;
            r.CRCApplicable = false;
            r.DecodeAttempted = false;
            r.DecodeUsable = false;
            r.DetectionAttempted = false;
            r.DetectionUsable = false;
            r.MeasurementAttempted = false;
            r.MeasurementUsable = false;
            r.ReceiverUsable = false;
            r.BlockingFlag = 1;
            r.UsedCCECount = 0;
            r.FailureReason = "control_blocked_no_nonoverlapping_pdcch_candidate";
        end
    end
    rows(k) = r;
end
T = struct2table(rows);
end

function [r,receivedAssignment] = localCompletePDCCHTrial(preparedPDCCH,observation,grantContext,snr_dB,k,nVar,replay)
% Receive-completion reducer for a retained control preparation. This stage
% never regenerates TX, propagates fading, or executes an RF chain.
cfgTrial = preparedPDCCH.ReceiverConfig;
receivedAssignment=struct();
tx = preparedPDCCH.Tx;
txInfo = preparedPDCCH.TxInfo;
grantRNTI = double(txInfo.RNTI);
dciFormatSeed = localResolvePDCCHGrantDCIFormat(grantContext, "DL");
dciBitsSeed = int8(sixgr.util.structGet(grantContext,"DCI.Bits",int8([])));
r = localMakeLinkTrialRow(cfgTrial,"DL",snr_dB,k);
r.Status = "FAIL";
r.CRCPass = NaN;
r.CRCApplicable = false;
tDecode = tic;
noiseVariance = [];
if isfinite(double(nVar)) && double(nVar)>=0
    noiseVariance = nVar;
end
[rx,rxInfo] = sixgr.link.completePDCCHReception(preparedPDCCH,observation, ...
    "NoiseVariance",noiseVariance);
controlLatency_ms = toc(tDecode)*1e3;
radioTTI_ms = localSlotDuration(cfgTrial)*1e3;
[be, bt] = localBitErrors(tx.DCIBits, rx.DCIBits);
dciCrcPass = logical(sixgr.util.structGet(rx, "Ok", false)) && ...
    double(sixgr.util.structGet(rx, "ErrFlag", 1)) == 0;
payloadMatch = logical(sixgr.util.structGet(rx, "DCIPayloadMatch", (be == 0) && (bt == numel(tx.DCIBits))));
ok = dciCrcPass && payloadMatch;
candidateT = sixgr.util.structGet(rxInfo, "CandidateResults", table());
if ~istable(candidateT)
    candidateT = table();
end
decodedDci = localDecodeObservedPDCCHGrantDCI( ...
    rx, tx, dciFormatSeed, grantContext, cfgTrial);
if rxInfo.ReceiverConfiguredMonitoring && rx.Ok
    receivedAssignment=sixgr.phy.pdcch.materializeConnectedDCI(rx,rxInfo,cfgTrial);
end
aggLevel = localPDCCHScalar(tx.PDCCH, "AggregationLevel", NaN);
usedCCEs = aggLevel;
availCCEs = localPDCCHAvailableCCEs(tx.PDCCH);
controlBits = double(sixgr.util.structGet(txInfo, "E", NaN));
r.TBSize_bits = double(numel(tx.DCIBits));
r.DCISize_bits = double(numel(tx.DCIBits));
r.BitsCompared = double(bt);
r.BitErrors = double(be);
r.CRCApplicable = true;
r.CRCPass = double(ok);
r.CRCOutcome = string(localPDCCHCRCOutcome(dciCrcPass, payloadMatch));
r.DCICrcPass = logical(dciCrcPass);
r.PDCCHPayloadMatch = logical(payloadMatch);
r.PDCCHCausalGrantDecodeOk = logical(sixgr.util.structGet(rx, "CausalGrantDecodeOk", ok));
r.PDCCHExpectedDCIBitCount = double(numel(tx.DCIBits));
r.PDCCHDecodedDCIBitCount = double(numel(sixgr.util.structGet(rx, "DCIBits", int8([]))));
r.PDCCHDCIBitsCompared = double(sixgr.util.structGet(rx, "DCIBitsCompared", bt));
r.PDCCHDCIBitErrors = double(sixgr.util.structGet(rx, "DCIBitErrors", be));
r.PDCCHMissedDetection = logical(sixgr.util.structGet(rx, "MissedDetection", ~dciCrcPass));
r.PDCCHFalseAlarm = logical(sixgr.util.structGet(rx, "FalseAlarm", dciCrcPass && ~payloadMatch));
r.PDCCHErrFlag = double(sixgr.util.structGet(rx, "ErrFlag", NaN));
r.DetectionMetric = 1 - (double(be) / max(double(bt), 1));
r.ConfiguredSNR_dB = double(sixgr.util.structGet(replay, "ConfiguredSNR_dB", snr_dB));
r.AppliedAWGNSNR_dB = double(sixgr.util.structGet(replay, "AppliedAWGNSNR_dB", NaN));
r.DesiredSignalPowerBeforeNoise = double(sixgr.util.structGet(replay, "DesiredSignalPowerBeforeNoise", NaN));
r.CompositeSignalPowerBeforeNoise = double(sixgr.util.structGet(replay, "CompositeSignalPowerBeforeNoise", NaN));
r.AppliedNoiseSNR_dB = double(sixgr.util.structGet(replay, "AppliedNoiseSNR_dB", NaN));
r.NoiseVarianceSource = string(sixgr.util.structGet(replay, "NoiseVarianceSource", ""));
r.ChannelModelApplied = string(sixgr.util.structGet(replay, "ChannelModelApplied", ""));
r.ChannelFadingApplied = logical(sixgr.util.structGet(replay, "ChannelFadingApplied", false));
r.AppliedLargeScaleGain_dB = double(sixgr.util.structGet(replay, "AppliedLargeScaleGain_dB", NaN));
r.AppliedLargeScaleLoss_dB = double(sixgr.util.structGet(replay, "AppliedLargeScaleLoss_dB", NaN));
r.AppliedBasePathloss_dB = double(sixgr.util.structGet(replay, "AppliedBasePathloss_dB", NaN));
r.AppliedPathloss_dB = double(sixgr.util.structGet(replay, "AppliedPathloss_dB", NaN));
r.AppliedShadowFading_dB = double(sixgr.util.structGet(replay, "AppliedShadowFading_dB", NaN));
r.AppliedO2I_dB = double(sixgr.util.structGet(replay, "AppliedO2I_dB", NaN));
r.AppliedLargeScaleGainSource = string(sixgr.util.structGet(replay, "AppliedLargeScaleGainSource", ""));
r.PowerContextAmplitudeUnit = string(sixgr.util.structGet( ...
    replay,"PowerContextAmplitudeUnit",""));
r.PowerContextTotalTxPower_dBm = double(sixgr.util.structGet( ...
    replay,"PowerContextTotalTxPower_dBm",NaN));
powerContext = sixgr.util.structGet(replay,"PowerContext",struct());
r.PowerContextTxGain_dB = double(sixgr.util.structGet( ...
    powerContext,"TxGain_dB",NaN));
r.PowerContextRxGain_dB = double(sixgr.util.structGet( ...
    powerContext,"RxGain_dB",NaN));
r.PowerContextAdditionalLoss_dB = double(sixgr.util.structGet( ...
    powerContext,"AdditionalLoss_dB",NaN));
r.CellTotalTxPower_dBm = double(sixgr.util.structGet( ...
    powerContext,"CellTotalTxPower_dBm",NaN));
r.EndpointPowerBudget_dBm = double(sixgr.util.structGet( ...
    powerContext,"EndpointPowerBudget_dBm",NaN));
r.ConcurrentTransmitterGrantCount = double(sixgr.util.structGet( ...
    powerContext,"ConcurrentTransmitterGrantCount",NaN));
r.GrantPowerFraction = double(sixgr.util.structGet( ...
    powerContext,"GrantPowerFraction",NaN));
r.GrantTargetTxPower_dBm = double(sixgr.util.structGet( ...
    powerContext,"GrantTargetTxPower_dBm",NaN));
r.ScheduledPowerPolicy = string(sixgr.util.structGet( ...
    powerContext,"ScheduledPowerPolicy",""));
r.ScheduledPowerAuthority = string(sixgr.util.structGet( ...
    powerContext,"ScheduledPowerAuthority",""));
r.SharedCellBudgetApplied = logical(sixgr.util.structGet( ...
    powerContext,"SharedCellBudgetApplied",false));
r.TxRFExecutionStatus = string(sixgr.util.structGet( ...
    replay,"TxRFExecutionStatus",""));
r.TxRFStageOrder = string(sixgr.util.structGet( ...
    replay,"TxRFStageOrder",""));
r.TxRFAppliedStageCount = double(sixgr.util.structGet( ...
    replay,"TxRFAppliedStageCount",0));
r.CompositeReceiverFrontEndApplied = logical(sixgr.util.structGet( ...
    replay,"CompositeReceiverFrontEndApplied",false));
r.CompositeReceiverFrontEndStatus = string(sixgr.util.structGet( ...
    replay,"CompositeReceiverFrontEndStatus",""));
r.ServingRSRP_dBm = double(sixgr.util.structGet(replay, "ServingRSRP_dBm", NaN));
r.ServingRSRPSource = string(sixgr.util.structGet(replay, "ServingRSRPSource", ""));
r.LargeScaleSINR_dB = double(sixgr.util.structGet(replay, "LargeScaleSINR_dB", NaN));
r.LargeScaleSINRSource = string(sixgr.util.structGet(replay, "LargeScaleSINRSource", ""));
r.InterferenceMode = string(sixgr.util.structGet(replay, "InterferenceMode", ""));
r.InjectedCFO_Hz = double(sixgr.util.structGet(replay, "InjectedCFO_Hz", NaN));
r.TrueCFO_Hz = r.InjectedCFO_Hz;
r.InjectedTimingOffset_samples = double(sixgr.util.structGet(replay, "InjectedTimingOffset_samples", 0));
r.TrueTimingOffset_samples = r.InjectedTimingOffset_samples;
r.IQImbalanceConfigured = logical(sixgr.util.structGet(replay, "IQImbalanceConfigured", false));
r.IQImbalanceApplied = logical(sixgr.util.structGet(replay, "IQImbalanceApplied", false));
r.IQImbalanceModel = string(sixgr.util.structGet(replay, "IQImbalanceModel", ""));
r.ConfiguredIQGainImbalance_dB = double(sixgr.util.structGet(replay, "ConfiguredIQGainImbalance_dB", NaN));
r.ConfiguredIQPhaseImbalance_deg = double(sixgr.util.structGet(replay, "ConfiguredIQPhaseImbalance_deg", NaN));
r.IQImbalanceMirrorPowerRatio_dB = double(sixgr.util.structGet(replay, "IQImbalanceMirrorPowerRatio_dB", NaN));
r.IQImbalanceImageRejection_dB = double(sixgr.util.structGet(replay, "IQImbalanceImageRejection_dB", NaN));
r.IQImbalanceIQPowerRatio_dB = double(sixgr.util.structGet(replay, "IQImbalanceIQPowerRatio_dB", NaN));
r.IQImbalanceIQCorrelation = double(sixgr.util.structGet(replay, "IQImbalanceIQCorrelation", NaN));
r.IQImbalanceEstimatedAlphaAbs = double(sixgr.util.structGet(replay, "IQImbalanceEstimatedAlphaAbs", NaN));
r.IQImbalanceEstimatedBetaAbs = double(sixgr.util.structGet(replay, "IQImbalanceEstimatedBetaAbs", NaN));
r.IQImbalanceMeasurementSource = string(sixgr.util.structGet(replay, "IQImbalanceMeasurementSource", ""));
r.IQImbalanceMeasurementStatus = string(sixgr.util.structGet(replay, "IQImbalanceMeasurementStatus", ""));
r.ReceiverHestSINR_dB = double(sixgr.util.structGet(rx, "ReceiverHestSINR_dB", NaN));
r.ReceiverHestSINRSource = string(sixgr.util.structGet(rx, "ReceiverHestSINRSource", ""));
r.ReceiverHestSINRValueRole = string(sixgr.util.structGet(rx, "ReceiverHestSINRValueRole", ""));
r.ReceiverHestSINRValueStatus = string(sixgr.util.structGet(rx, "ReceiverHestSINRValueStatus", ""));
r.ReceiverHestSINRNAReason = string(sixgr.util.structGet(rx, "ReceiverHestSINRNAReason", ""));
r.MeasuredTrialSINR_dB = NaN;
r.MeasuredTrialSINRSource = "";
r.MeasuredTrialSINRValueRole = "unavailable";
r.MeasuredTrialSINRValueStatus = "unavailable";
r.MeasuredTrialSINRNAReason = "pdcch_has_no_data_post_equalization_sinr_measurement";
r.NoiseVariance = double(sixgr.util.structGet(rx, "NoiseVar", NaN));
r.NoiseVarStatus = string(sixgr.util.structGet(rx, "NoiseVarStatus", ""));
r.NoiseVarSource = string(sixgr.util.structGet(rx, "NoiseVarSource", ""));
r.NoiseVarReason = string(sixgr.util.structGet(rx, "NoiseVarReason", ""));
if strlength(strtrim(r.NoiseVarStatus)) == 0 && isfinite(r.NoiseVariance) && r.NoiseVariance > 0
    r.NoiseVarStatus = "OK";
    r.NoiseVarSource = "pdcch_receiver_noise_variance";
elseif ~(isfinite(r.NoiseVariance) && r.NoiseVariance > 0)
    r.NoiseVarStrictFailure = true;
    r.NoiseVarReason = "pdcch_noise_variance_missing_or_nonpositive";
elseif r.NoiseVarStatus ~= "OK"
    r.NoiseVarStrictFailure = true;
end
if localThermalNoiseSINRUnavailable(replay)
    r = localMarkControlSINRUnavailable(r, ...
        "thermal_noise_sinr_unavailable_without_runtime_rx_power_or_pathloss");
end
r.EVM_rms = double(sixgr.util.structGet(rx, "EVM_rms", NaN));
r.DecodeAttempted = true;
r.DecodeUsable = logical(ok);
r.DetectionAttempted = true;
r.DetectionSuccess = logical(ok);
r.DetectionUsable = isfinite(r.DetectionMetric) && height(candidateT) > 0;
r.MeasurementAttempted = true;
r.MeasurementUsable = isfinite(r.ReceiverHestSINR_dB) && ...
    sixgr.util.isAcceptableSINRStatus(r.ReceiverHestSINRValueStatus);
% Primary evidence is this actual received candidate set. Independent
% noise-only false-alarm campaigns remain separate observations, not
% a second RF execution used to accept or reject this scheduled DCI.
r.FalseAlarmFlag = double(r.PDCCHFalseAlarm);
r.FalseAlarmClassification = "actual_received_dci_payload_mismatch";
r.NoiseFalseAlarmFlag = NaN;
r.PDCCHObservationStartSample = rxInfo.ObservationStartSample;
r.PDCCHObservationEndSampleExclusive = rxInfo.ObservationEndSampleExclusive;
r.PDCCHObservationCompletionTime_s = rxInfo.ObservationCompletionTime_s;
r.PDCCHMinimumReceiveSamples = rxInfo.ReceiveExtent.MinimumReceiveSamples;
r.PDCCHDemodulatedSymbols = rxInfo.DemodulatedSymbols;
r.PDCCHReceivePaddingApplied = rxInfo.ReceivePaddingApplied;
r.BlockingFlag = double(isfinite(aggLevel) && isfinite(availCCEs) && aggLevel > availCCEs);
r.BlindDecodeCount = double(sixgr.util.structGet(rxInfo, "NumDecodeHypothesesTried", height(candidateT)));
r.AvailableCCECount = availCCEs;
r.UsedCCECount = usedCCEs;
r.NonOverlappedCCEUsage = usedCCEs / max(availCCEs, 1);
r.AggregationLevel = aggLevel;
r.CandidatesAttempted = double(rxInfo.NumCandidatesTried);
r.PDCCHBlindSearchEnabled = logical(sixgr.util.structGet(rxInfo, "BlindSearch", false));
r.PDCCHCandidatesAvailable = double(sixgr.util.structGet(rxInfo, "NumCandidatesAvailable", height(candidateT)));
r.PDCCHCandidatesAttempted = r.CandidatesAttempted;
txCandidateIndex = localPDCCHScalar(tx.PDCCH, "AllocatedCandidate", 1) - 1;
selectedAggregationLevel = double(sixgr.util.structGet( ...
    rx, "CandidateAggregationLevel", NaN));
selectedCandidateIndex = double(sixgr.util.structGet( ...
    rx, "CandidateIndexWithinAggregation", NaN));
r.PDCCHCandidateIndex = double(txCandidateIndex);
r.PDCCHCandidateFlatIndex = double(sixgr.util.structGet( ...
    rx, "CandidateFlatIndex", sixgr.util.structGet(rx, "CandidateIndex", NaN)));
r.PDCCHSelectedAggregationLevel = selectedAggregationLevel;
r.PDCCHSelectedCandidateIndex = selectedCandidateIndex;
r.PDCCHSelectedCCEIndex = localResolvePDCCHFirstCCE( ...
    cfgTrial, tx, selectedAggregationLevel, selectedCandidateIndex, grantRNTI);
r.SelectedCCEIndex = r.PDCCHSelectedCCEIndex;
r.TxCCEIndex = localResolvePDCCHFirstCCE( ...
    cfgTrial, tx, aggLevel, txCandidateIndex, grantRNTI);
r.PDCCHTxCCEIndex = r.TxCCEIndex;
r.PDCCHDCICrcRNTI = double(sixgr.util.structGet(txInfo, "DCICrcRNTI", NaN));
r.PDCCHScramblingRNTI = double(sixgr.util.structGet(txInfo, "PDCCHScramblingRNTI", NaN));
r.PDCCHEncodedBits = controlBits;
r.PDCCHRECount = double(sixgr.util.structGet(txInfo, "NumPDCCHRE", numel(tx.PDCCHInd)));
r.PDCCHDMRSRECount = double(sixgr.util.structGet(txInfo, "NumDMRSRE", numel(tx.DMRSInd)));
r.PDCCHCandidateErrFlagVector = localFormatNumericVector(localColumnOrDefault(candidateT, "ErrFlag", nan(height(candidateT), 1)));
r.PDCCHCandidateDecodeOKVector = localFormatNumericVector(double(localColumnOrDefault(candidateT, "DecodeOK", false(height(candidateT), 1))));
r.PDCCHCandidateSINRVector_dB = localFormatNumericVector(localColumnOrDefault(candidateT, "ReceiverHestSINR_dB", nan(height(candidateT), 1)));
r.PDCCHCandidateRECountVector = localFormatNumericVector(localColumnOrDefault(candidateT, "PDCCHRECount", nan(height(candidateT), 1)));
r.PDCCHCandidateDMRSRECountVector = localFormatNumericVector(localColumnOrDefault(candidateT, "DMRSRECount", nan(height(candidateT), 1)));
r.PDCCHCandidateAggregationLevelVector = localFormatNumericVector(localColumnOrDefault(candidateT, "AggregationLevel", nan(height(candidateT), 1)));
r.PDCCHCandidateWithinAggregationVector = localFormatNumericVector(localColumnOrDefault(candidateT, "CandidateIndexWithinAggregation", nan(height(candidateT), 1)));
r.PDCCHHypothesisReductionClass = string(sixgr.util.structGet(rxInfo, "HypothesisReductionClass", ""));
r.PDCCHEquivalentValidHypothesisCount = double(sixgr.util.structGet(rxInfo, "EquivalentValidHypothesisCount", 0));
r.PDCCHAmbiguousValidHypothesisCount = double(sixgr.util.structGet(rxInfo, "AmbiguousHypothesisCount", 0));
r.PDCCHCRCDecodeSource = "nrDCIDecode_crc_masked_by_rnti";
r.PDCCHBlindDecodeEvidenceSource = "nrPDCCHSpace_nrPDCCHDecode_nrDCIDecode";
r.PDCCHCCE_REGMappingEvidence = "nrPDCCHResources_coreset_search_space_candidate_mapping";
r.PDCCHREGMappingAvailable = ~isempty(tx.PDCCHInd) && ~isempty(tx.DMRSInd);
r.PDCCHCORESETDuration = localPDCCHScalar(tx.PDCCH.CORESET, "Duration", NaN);
r.PDCCHCORESETFrequencyResources = localFormatNumericVector(localPDCCHScalarVector(tx.PDCCH.CORESET, "FrequencyResources"));
r.PDCCHSearchSpaceNumCandidates = localFormatNumericVector(localPDCCHScalarVector(tx.PDCCH.SearchSpace, "NumCandidates"));
configuredCORESETId = double(sixgr.util.structGet(cfgTrial, ...
    "phy.pdcch.coreset.id", 0));
configuredSearchSpaceId = double(sixgr.util.structGet(cfgTrial, ...
    "phy.pdcch.searchSpace.id", 1));
r.CORESETId = localPDCCHScalar(tx.PDCCH.CORESET, ...
    "CORESETID", localPDCCHScalar(tx.PDCCH.CORESET, ...
    "ID", configuredCORESETId));
r.SearchSpaceId = localPDCCHScalar(tx.PDCCH.SearchSpace, ...
    "SearchSpaceID", localPDCCHScalar(tx.PDCCH.SearchSpace, ...
    "ID", configuredSearchSpaceId));
% CandidateIndex is the transmitted zero-based candidate within the
% configured aggregation level. The receiver's flat blind-attempt
% ordinal and selected hypothesis are exported separately above.
r.CandidateIndex = double(txCandidateIndex);
r.DCIFormat = string(dciFormatSeed);
r.DCIId = string(sixgr.util.structGet(decodedDci, "PayloadHash", ""));
r.DCIFieldsHash = string(localHashDecodedPDCCHGrantFields(decodedDci, r.PDCCHDCICrcRNTI));
r.DecodedDCIHARQProcessId = double(sixgr.util.structGet(decodedDci, "Fields.harq_process", NaN));
r.DecodedDCIPRBStart = double(sixgr.util.structGet(decodedDci, "Fields.prb_start", NaN));
r.DecodedDCIAllocatedPRBCount = double(sixgr.util.structGet(decodedDci, "Fields.num_prb", NaN));
r.DecodedDCISymbolStart = double(sixgr.util.structGet(decodedDci, "Fields.symbol_start", NaN));
r.DecodedDCINumSymbols = double(sixgr.util.structGet(decodedDci, "Fields.num_symbols", NaN));
r.DecodedDCIMCSIndex = double(sixgr.util.structGet(decodedDci, "Fields.mcs", NaN));
r.DecodedDCIRV = double(sixgr.util.structGet(decodedDci, "Fields.rv", NaN));
r.DecodedDCINDI = double(sixgr.util.structGet(decodedDci, "Fields.ndi", NaN));
r.DecodedDCITimeDomainAssignmentIndex = double(sixgr.util.structGet(decodedDci, ...
    "Fields.time_domain_assignment_index",sixgr.util.structGet(decodedDci,"Fields.time_resource_assignment",NaN)));
r.DecodedDCITCICodepoint = double(sixgr.util.structGet(decodedDci,"Fields.transmission_configuration_indication",NaN));
if ~isempty(fieldnames(receivedAssignment))
    receivedFields=sixgr.truth.connectedDCIAssignmentEvidence(receivedAssignment);
    for fieldName=string(fieldnames(receivedFields)).'
        r.(fieldName)=receivedFields.(fieldName);
    end
end
r.LinkedGrantId = string(sixgr.util.structGet(grantContext, "GrantContextId", ""));
r.LinkedPDSCHOrPUSCH = upper(string(sixgr.util.structGet(grantContext, "Direction", "")));
r.PDCCHGridHash = localComplexSHA256(tx.Grid);
r.PDCCHWaveformHash = localComplexSHA256(tx.Waveform);
r.PDCCHResourceHash = localPDCCHResourceHash(tx.PDCCHInd, tx.DMRSInd);
r.ControlCapacityBits = controlBits;
r.ControlCapacityUtilization = double(numel(tx.DCIBits)) / max(controlBits, 1);
r.CORESETUtilization = usedCCEs / max(availCCEs, 1);
r.ComputeLatency_ms = controlLatency_ms;
r.ProcedureDelay_ms = NaN;
r.AirInterfaceTTI_ms = radioTTI_ms;
% Legacy alias preserved for backward compatibility with older exports.
% It mirrors the control opportunity duration, not wall-clock decode runtime.
r.ControlLatency_ms = radioTTI_ms;
r.ResourceExtractionAttempted = true;
r.ResourceExtractionAvailable = ~isempty(tx.PDCCHInd) && ~isempty(rx.EqualizedSymbols);
r.ChannelEstimateAttempted = true;
r.ChannelEstimateAvailable = localHasFiniteNumericEvidence(sixgr.util.structGet(rx, "ChannelEstimate", []));
r.ChannelEstimateSource = "nrChannelEstimate_pdcch_dmrs";
r = sixgr.truth.bindReceiverSINRApplicability(r);
r.EqualizationAttempted = true;
r.EqualizationAvailable = localHasFiniteNumericEvidence(sixgr.util.structGet(rx, "EqualizedSymbols", []));
noiseOk = isfinite(r.NoiseVariance) && r.NoiseVariance > 0 && strcmpi(string(r.NoiseVarStatus), "OK") && ...
    ~logical(r.NoiseVarStrictFailure);
strictOk = logical(ok) && logical(r.DetectionUsable) && logical(r.MeasurementUsable) && ...
    logical(r.ChannelEstimateAvailable) && logical(r.ResourceExtractionAvailable) && ...
    logical(r.EqualizationAvailable) && noiseOk && ~logical(r.FalseAlarmFlag);
r.StrictReceiverEvidenceOk = logical(strictOk);
r.StrictOk = logical(strictOk);
r.ReceiverUsable = logical(strictOk);
r.TruthStatus = "real_pdcch_waveform_blind_dci_crc_evidence";
r.SourceClassification = "active_integrated";
r.RuntimeMaterializationStatus = "active_integrated_pdcch_blind_dci_crc_cce_reg_evidence";
r.RuntimeEvidenceSource = "sixgr.phy.dl.PDCCH_Tx|sixgr.phy.dl.PDCCH_Rx";
r.RuntimeIntegrationMode = "coupled_slot_runtime";
r.RuntimeTransportMode = "pdcch_tx_runtime_channel_rf_noise_pdcch_rx";
r.RuntimeStageWaveformsRequired = true;
r.RuntimeStageWaveformsUsed = true;
r.RuntimeSelfLoopWaveformsUsed = false;
r.RuntimeChannelStateUsed = logical(sixgr.util.structGet( ...
    replay, "RuntimeChannelStateUsed", false));
injectedVariance = double(sixgr.util.structGet(replay,"InjectedNoiseVariance",NaN));
r.RuntimeNoiseApplied = isfinite(injectedVariance) && injectedVariance > 0;
r.RuntimeNoiseVarianceMean = double(nVar);
r.RuntimeChannelLinkKeys = string(sixgr.util.structGet( ...
    replay, "RuntimeChannelLinkKey", ""));
r.RuntimeStageCount = 5;
if strictOk
    r.Status = "PASS";
else
    r.Status = "FAIL";
    r.FailureReason = localPDCCHStrictFailureReason(r, rx, be, bt, payloadMatch, dciCrcPass, noiseOk);
end
if ~isempty(dciBitsSeed)
    r.Notes = "Grant-coupled PDCCH DCI payload decoded through blind candidate search, channel estimation, MMSE equalization, and RNTI-masked DCI CRC.";
end
end

function tf = localThermalNoiseSINRUnavailable(replay)
noiseMode = lower(strtrim(string(sixgr.util.structGet(replay, "NoiseOperatingMode", ""))));
if noiseMode ~= "receiver_noise_figure_thermal_noise"
    tf = false;
    return;
end
servingSource = lower(strtrim(string(sixgr.util.structGet(replay, "ServingRxPowerSource", ""))));
noiseSource = lower(strtrim(string(sixgr.util.structGet(replay, "NoisePowerSource", ""))));
tf = servingSource == "unavailable_missing_pathloss_or_runtime_rx_power" || ...
    noiseSource == "thermal_noise_unavailable_missing_pathloss_or_runtime_rx_power";
end

function r = localMarkControlSINRUnavailable(r, reason)
reason = string(reason);
r.ReceiverHestSINR_dB = NaN;
r.ReceiverHestSINRSource = "";
r.ReceiverHestSINRValueRole = "unavailable";
r.ReceiverHestSINRValueStatus = "unavailable";
r.ReceiverHestSINRNAReason = reason;
r.MeasuredTrialSINR_dB = NaN;
r.MeasuredTrialSINRSource = "";
r.MeasuredTrialSINRValueRole = "unavailable";
r.MeasuredTrialSINRValueStatus = "unavailable";
r.MeasuredTrialSINRNAReason = reason;
r.MeasuredSINR_dB = NaN;
r.SINRValueRole = "unavailable";
r.SINRSource = "";
r.SINRValueStatus = "unavailable";
r.SINRValueDefinition = "no_control_sinr_observation_available_without_runtime_noise_power_anchor";
end

function [y,nVar,replay,updatedRuntimeChannelState] = ...
        localApplyPDCCHChannelAndNoise(prepared,snr_dB,initialRuntimeChannelState)
cfg = prepared.ReceiverConfig;
tx = prepared.Tx;
txInfo = prepared.TxInfo;
x = prepared.TransmitSamples;
if nargin < 3 || ~isstruct(initialRuntimeChannelState)
    initialRuntimeChannelState = struct();
end
if ~isfield(txInfo, "OFDM")
    try
        txInfo.OFDM = nrOFDMInfo(tx.Carrier);
    catch
        txInfo.OFDM = struct();
    end
end
% Execute the same physical ordering used by data channels: configured
% transmit power/PA, transmitter RF, per-link fading, large-scale loss,
% thermal noise, then the shared receiver RF/ADC.  PDCCH must not apply a
% combined RF chain after the channel or inject noise after the ADC.
[x,powerContext] = sixgr.rf.applyPowerContext(x,cfg,"DL",txInfo);
cfg = sixgr.util.structSet(cfg,"lls6g.runtimePowerContext",powerContext);
sampleRateHz = localResolvePDCCHSampleRate(tx,txInfo);
txRfOut = sixgr.rf.applyRFImpairmentChain(x,cfg, ...
    "SampleRateHz",sampleRateHz, ...
    "Direction","DL", ...
    "MeasurementPoint","tx_output", ...
    "Endpoint","tx", ...
    "StrictMutationRequired",false, ...
    "UseLegacyGlobalConfig",false, ...
    "ApplyPA",false, ...
    "ApplyADC",false);
x = cast(txRfOut.Waveform,"like",x);
cfg = sixgr.util.structSet(cfg,"lls6g.txRFImpairmentReplay",txRfOut.Replay);
state = sixgr.link.initWaveformTruthChannelState(cfg,tx,txInfo, ...
    "InitialRuntimeChannelState",initialRuntimeChannelState);
sampleRateHz = double(sixgr.util.structGet(state, "SampleRate_Hz", localResolvePDCCHSampleRate(tx, txInfo)));
y = x;
replay = struct( ...
    "ConfiguredSNR_dB", double(snr_dB), ...
    "AppliedAWGNSNR_dB", double(snr_dB), ...
    "InjectedNoiseVariance", NaN, ...
    "NoiseVarianceSource", "", ...
    "ChannelModelApplied", string(sixgr.util.structGet(cfg, "channel.model", "AWGN")), ...
    "ChannelFadingApplied", false, ...
    "PowerContext",powerContext, ...
    "PowerContextAmplitudeUnit",string(powerContext.WaveformAmplitudeUnit), ...
    "PowerContextTotalTxPower_dBm",double(powerContext.TotalTxPower_dBm), ...
    "TxRFExecutionStatus",string(sixgr.util.structGet( ...
        txRfOut.Replay,"RFExecutionStatus","applied_or_identity")), ...
    "TxRFStageOrder",string(sixgr.util.structGet( ...
        txRfOut.Replay,"RFStageOrder","")), ...
    "TxRFAppliedStageCount",double(sixgr.util.structGet( ...
        txRfOut.Replay,"RFAppliedStageCount",0)));

[y, channelReplay, state] = sixgr.link.applyRuntimeFadingChannel(x, state); %#ok<ASGLU>
chFields = fieldnames(channelReplay);
for chIdx = 1:numel(chFields)
    replay.(chFields{chIdx}) = channelReplay.(chFields{chIdx});
end

cfgReplay = sixgr.util.structSet(cfg, "channel.snr_dB", double(snr_dB));
% Large-scale link budget belongs between channel and receiver noise.  RF
% execution is split across the already-completed TX boundary and the
% composite RX boundary below.
[y, impairmentReplay] = sixgr.link.applyWaveformImpairments(y, ...
    cfgReplay,sampleRateHz,"ApplyRFChain",false);
fields = fieldnames(impairmentReplay);
for ii = 1:numel(fields)
    replay.(fields{ii}) = impairmentReplay.(fields{ii});
end
replay.ChannelModelApplied = string(sixgr.util.structGet(cfg, "channel.model", replay.ChannelModelApplied));
replay.ChannelFadingApplied = logical(sixgr.util.structGet(channelReplay, "ChannelFadingApplied", false));
desiredWaveform = y;
[preFrontEndWaveform, preFrontEndNVar, noiseInfo] = ...
    localPDCCHAddAwgnFromReplay(y,replay,desiredWaveform,txInfo);
replay.InjectedNoiseVariance = double(preFrontEndNVar);
noiseFields = fieldnames(noiseInfo);
for ni = 1:numel(noiseFields)
    replay.(noiseFields{ni}) = noiseInfo.(noiseFields{ni});
end
if isfinite(preFrontEndNVar) && preFrontEndNVar > 0 && ...
        strlength(strtrim(string(sixgr.util.structGet( ...
        replay,"NoiseVarianceSource","")))) == 0
    replay.NoiseVarianceSource = "pdcch_replay_reference_waveform_awgn";
end
[y,replay] = sixgr.link.applyCompositeReceiverFrontEnd( ...
    preFrontEndWaveform,cfgReplay,sampleRateHz,replay,"Direction","DL");
replay = sixgr.link.applyCompositeFrontEndVarianceReplay(replay);
nVar = double(sixgr.util.structGet(replay, ...
    "InjectedNoiseVariancePostCompositeFrontEnd",preFrontEndNVar));
% A nonlinear receiver cannot be replayed independently on noise and then
% described as the disturbance in the original capture. Use its resolved
% input-to-output variance where valid, or actual received DM-RS estimation.
updatedRuntimeChannelState = sixgr.util.structGet( ...
    state,"RuntimeChannelState",struct());
end

function sampleRateHz = localResolvePDCCHSampleRate(tx, txInfo)
sampleRateHz = [];
if isstruct(txInfo)
    sampleRateHz = sixgr.util.structGet(txInfo, "OFDM.SampleRate", []);
end
if isempty(sampleRateHz) && isstruct(tx)
    try
        ofdmInfo = nrOFDMInfo(tx.Carrier);
        sampleRateHz = double(sixgr.util.structGet(ofdmInfo, "SampleRate", []));
    catch
        sampleRateHz = [];
    end
end
if isempty(sampleRateHz) || ~(isscalar(sampleRateHz) && isfinite(double(sampleRateHz)) && double(sampleRateHz) > 0)
    error('sixgr:truth:PDCCHSampleRateUnavailable', ...
        'PDCCH noise and timing require its actual OFDM sample rate.');
else
    sampleRateHz = double(sampleRateHz);
end
end

function [y, nVar, noiseInfo] = localPDCCHAddAwgnFromReplay(x, replay, referenceWaveform, txInfo)
noiseInfo = localPDCCHNoiseCalibrationInfo(x, referenceWaveform, NaN, "unavailable", replay);
noiseMode = string(sixgr.util.structGet(replay, "NoiseOperatingMode", "receiver_noise_figure_thermal_noise"));
if noiseMode == "receiver_noise_figure_thermal_noise"
    nVar = localPDCCHResolveThermalNoiseVariance(replay, referenceWaveform, txInfo);
    noiseInfo = localPDCCHNoiseCalibrationInfo(x, referenceWaveform, nVar, "thermal_noise_plus_receiver_nf", replay);
    if isfinite(nVar) && nVar > 0
        n = sqrt(nVar / 2) .* (randn(size(x), "like", real(x)) + 1i * randn(size(x), "like", real(x)));
        y = x + cast(n, "like", x);
        return;
    end
    error('sixgr:truth:PDCCHNoiseVarianceUnavailable', ...
        'The receiver thermal-noise operating mode requires a resolved physical noise PSD and sample rate.');
end
appliedSNR_dB = double(sixgr.util.structGet(replay, "AppliedAWGNSNR_dB", NaN));
nVar = localPDCCHResolveConfiguredSNRNoiseVariance(referenceWaveform, appliedSNR_dB, txInfo);
noiseInfo = localPDCCHNoiseCalibrationInfo(x, referenceWaveform, nVar, "standalone_awgn_snr_argument_post_channel_units", replay);
if isfinite(nVar) && nVar >= 0
    if nVar > 0
        n = sqrt(nVar / 2) .* (randn(size(x), "like", real(x)) + 1i * randn(size(x), "like", real(x)));
        y = x + cast(n, "like", x);
    else
        y = x;
    end
    return;
end
error('sixgr:truth:PDCCHNoiseVarianceUnavailable', ...
    'Configured-SNR noise requires the actual useful-symbol signal power and resolved SNR.');
end

function info = localPDCCHNoiseCalibrationInfo(compositeWaveform, desiredWaveform, nVar, source, replay)
desiredPower = NaN;
compositePower = NaN;
if ~isempty(desiredWaveform)
    desiredPower = mean(abs(double(desiredWaveform(:))).^2, "omitnan");
end
if ~isempty(compositeWaveform)
    compositePower = mean(abs(double(compositeWaveform(:))).^2, "omitnan");
end
appliedSNR = double(sixgr.util.structGet(replay, "AppliedAWGNSNR_dB", NaN));
if isfinite(desiredPower) && desiredPower > 0 && isfinite(nVar) && nVar > 0
    appliedSNR = 10 * log10(desiredPower / nVar);
end
info = struct( ...
    "DesiredSignalPowerBeforeNoise", double(desiredPower), ...
    "CompositeSignalPowerBeforeNoise", double(compositePower), ...
    "AppliedNoiseSNR_dB", double(appliedSNR), ...
    "NoiseVarianceSource", char(string(source)));
end

function nVar = localPDCCHResolveConfiguredSNRNoiseVariance(referenceWaveform, snr_dB, txInfo)
nVar = NaN;
snr_dB = double(snr_dB);
if ~(isscalar(snr_dB) && isfinite(snr_dB)) || isempty(referenceWaveform)
    return;
end
refPower = localPDCCHUsefulOFDMReferencePower(referenceWaveform, txInfo);
if ~(isfinite(refPower) && refPower >= 0)
    return;
end
nVar = refPower / max(10.^(snr_dB / 10), eps);
end

function nVar = localPDCCHResolveThermalNoiseVariance(replay, referenceWaveform, txInfo) %#ok<INUSD>
nVar = sixgr.link.resolveReceiverThermalNoiseVariance(replay);
end

function refPower = localPDCCHUsefulOFDMReferencePower(waveform, txInfo)
refPower = NaN;
if isempty(waveform)
    return;
end
ofdmInfo = sixgr.util.structGet(txInfo, "OFDM", struct());
nfft = double(sixgr.util.structGet(ofdmInfo, "Nfft", NaN));
cpLens = double(sixgr.util.structGet(ofdmInfo, "CyclicPrefixLengths", []));
if ~(isfinite(nfft) && nfft > 0 && ~isempty(cpLens))
    refPower = mean(abs(double(waveform(:))).^2, "omitnan");
    return;
end
cpLens = cpLens(:);
idx = [];
offset = 0;
nSamp = size(waveform, 1);
while offset < nSamp
    for s = 1:numel(cpLens)
        cp = max(0, round(double(cpLens(s))));
        useful = offset + cp + (1:round(nfft));
        useful = useful(useful <= nSamp);
        idx = [idx useful]; %#ok<AGROW>
        offset = offset + cp + round(nfft);
        if offset >= nSamp
            break;
        end
    end
end
if isempty(idx)
    refPower = mean(abs(double(waveform(:))).^2, "omitnan");
else
    refPower = mean(abs(double(waveform(idx, :))).^2, "all", "omitnan");
end
end

function T = localBuildMissingPDCCHGrantBindingTrial(cfg, snr_dB, reason)
r = localMakeLinkTrialRow(cfg, "DL", snr_dB, 1);
r.Status = "NA";
r.StrictOk = false;
r.CRCApplicable = false;
r.CRCPass = NaN;
r.DecodeAttempted = false;
r.DecodeUsable = false;
r.DetectionAttempted = false;
r.DetectionUsable = false;
r.MeasurementAttempted = false;
r.MeasurementUsable = false;
r.ReceiverUsable = false;
r.GrantValid = false;
r.NegativeExpectedOk = false;
r.DCICrcPass = false;
r.PDCCHPayloadMatch = false;
r.PDCCHCausalGrantDecodeOk = false;
r.PDCCHMissedDetection = false;
r.PDCCHFalseAlarm = false;
r.NoiseVarStatus = "NOT_APPLICABLE";
r.NoiseVarSource = "pdcch_decode_not_attempted";
r.NoiseVarReason = string(reason);
r.ReceiverHestSINRValueStatus = "not_applicable";
r.ReceiverHestSINRNAReason = string(reason);
r.MeasuredTrialSINRValueStatus = "not_applicable";
r.MeasuredTrialSINRNAReason = string(reason);
r.RuntimeMaterializationStatus = "active_integrated_grant_coupled_pdcch_binding_guard";
r.ValueStatus = "decoded_dci_missing";
r.FailureReason = string(reason);
r.TruthStatus = "runtime_pdcch_binding_missing";
r.Notes = "Decoded PDCCH/DCI evidence was not available for this scheduled grant.";
T = struct2table(r, "AsArray", true);
end

function reason = localPDCCHDecodeFailureReason(rx, bitErrors, bitsCompared)
if ~logical(sixgr.util.structGet(rx, "Ok", false))
    errFlag = double(sixgr.util.structGet(rx, "ErrFlag", NaN));
    if isfinite(errFlag) && errFlag ~= 0
        reason = "pdcch_dci_crc_failed";
    else
        reason = "pdcch_decode_not_ok";
    end
else
    reason = "pdcch_dci_bit_mismatch_after_crc";
end
bitErrors = double(bitErrors);
bitsCompared = double(bitsCompared);
if isfinite(bitErrors) && bitErrors > 0 && isfinite(bitsCompared) && bitsCompared > 0
    reason = reason + "_bit_errors_" + string(round(bitErrors)) + "_of_" + string(round(bitsCompared));
end
noiseStatus = string(sixgr.util.structGet(rx, "NoiseVarStatus", ""));
if strlength(strtrim(noiseStatus)) > 0 && noiseStatus ~= "OK"
    reason = reason + "_noisevar_" + noiseStatus;
end
end

function outcome = localPDCCHCRCOutcome(dciCrcPass, payloadMatch)
if logical(dciCrcPass) && logical(payloadMatch)
    outcome = "pass";
elseif logical(dciCrcPass)
    outcome = "crc_pass_payload_mismatch";
else
    outcome = "fail";
end
end

function reason = localPDCCHStrictFailureReason(r, rx, bitErrors, bitsCompared, payloadMatch, dciCrcPass, noiseOk)
parts = strings(0, 1);
if ~logical(dciCrcPass)
    parts(end+1, 1) = "pdcch_dci_crc_failed"; %#ok<AGROW>
end
if ~logical(payloadMatch)
    parts(end+1, 1) = localPDCCHDecodeFailureReason(rx, bitErrors, bitsCompared); %#ok<AGROW>
end
if ~logical(r.DetectionUsable)
    parts(end+1, 1) = "pdcch_blind_candidate_detection_evidence_missing"; %#ok<AGROW>
end
if ~logical(r.MeasurementUsable)
    parts(end+1, 1) = "pdcch_receiver_hest_sinr_missing_or_not_ok"; %#ok<AGROW>
end
if ~logical(r.ChannelEstimateAvailable)
    parts(end+1, 1) = "pdcch_dmrs_channel_estimate_missing"; %#ok<AGROW>
end
if ~logical(r.ResourceExtractionAvailable)
    parts(end+1, 1) = "pdcch_resource_extraction_missing"; %#ok<AGROW>
end
if ~logical(r.EqualizationAvailable)
    parts(end+1, 1) = "pdcch_equalized_symbol_evidence_missing"; %#ok<AGROW>
end
if ~logical(noiseOk)
    parts(end+1, 1) = "pdcch_noise_variance_missing_or_not_ok"; %#ok<AGROW>
end
if logical(r.FalseAlarmFlag)
    parts(end+1, 1) = "pdcch_actual_received_false_grant_decode"; %#ok<AGROW>
end
if isempty(parts)
    parts(end+1, 1) = "pdcch_strict_receiver_evidence_incomplete"; %#ok<AGROW>
end
reason = strjoin(parts, ";");
end

function cfgTrial = localResolvePDCCHTrialConfig(cfg, snr_dB, trialIdx, nTrials, grantContext)
cfgTrial = cfg;
levels = double(sixgr.util.structGet(cfg, "phy.pdcch.aggregationLevels", ...
    sixgr.util.structGet(cfg, "control.aggregation_levels", ...
    sixgr.util.structGet(cfg, "ctrl6gr.StudyAggregationLevels", ...
    sixgr.util.structGet(cfg, "phy.pdcch.aggregationLevel", 4)))));
levels = unique(levels(ismember(levels, [1 2 4 8 16])), "stable");
if isempty(levels)
    levels = 4;
end
levels = sixgr.phy.pdcch.resolveExecutableAggregationLevels(cfg, levels);
if nargin >= 5 && isstruct(grantContext) && ~isempty(fieldnames(grantContext))
    aggLevel = localSelectGrantPDCCHAggregationLevel(cfg, levels, snr_dB);
else
    nTrials = max(1, round(double(nTrials)));
    idx = mod(max(1, round(double(trialIdx))) - 1, numel(levels)) + 1;
    if nTrials == 1
        aggLevel = localSelectPDCCHAggregationLevel(levels, snr_dB);
    else
        aggLevel = levels(idx);
    end
end
cfgTrial = sixgr.util.structSet(cfgTrial, "phy.pdcch.aggregationLevel", double(aggLevel));
cfgTrial = sixgr.util.structSet(cfgTrial, "phy.pdcch.blindSearch", ...
    logical(sixgr.util.structGet(cfg, "phy.pdcch.blindSearch", false)));
cfgTrial = sixgr.util.structSet(cfgTrial, "lls6g.userContext.RuntimeSignalFamily", "PDCCH");
cfgTrial = sixgr.util.structSet(cfgTrial, "phy.runtimeSignalFamily", "PDCCH");
% PDCCH is always transmitted by the gNB and received by the UE, including
% when its DCI schedules a future UL grant.  The scheduled data direction
% must not leak into RF gains, noise figure or runtime-channel identity.
cfgTrial = sixgr.util.structSet(cfgTrial, ...
    "lls6g.userContext.RuntimeCurrentDirection","DL");
cfgTrial = sixgr.util.structSet(cfgTrial, ...
    "lls6g.userContext.Direction","DL");
if nargin >= 5 && isstruct(grantContext) && ~isempty(fieldnames(grantContext))
    % An UL DCI is carried in its DL control slot, not the future PUSCH
    % data slot. Bind waveform construction, channel time and RE evidence
    % to that same absolute control occasion, including frame wrap.
    controlSlot = sixgr.truth.resolvePDCCHControlSlot(grantContext, ...
        sixgr.util.structGet(cfg, "lls6g.runtime.AbsoluteSlotIndexOneBased", NaN));
    cfgTrial = sixgr.phy.grid.applyRuntimeCarrierTimeline(cfgTrial, controlSlot);
    cfgTrial = sixgr.util.structSet(cfgTrial, "lls6g.userContext.RuntimeSlotStartTime_s", ...
        (double(controlSlot) - 1) * sixgr.time.slotDurationSec(cfgTrial));
end
end

function aggLevel = localSelectGrantPDCCHAggregationLevel(cfg, levels, snr_dB)
levels = unique(double(levels(ismember(levels, [1 2 4 8 16]))), "stable");
if isempty(levels)
    levels = 4;
end
policy = lower(strtrim(string(sixgr.util.structGet(cfg, "phy.pdcch.aggregationSelectionPolicy", "snr_threshold"))));
configuredAL = double(sixgr.util.structGet(cfg, "phy.pdcch.schedulerAggregationLevel", NaN));
if (policy == "configured_scheduler_level") && isfinite(configuredAL)
    if any(levels == configuredAL)
        aggLevel = configuredAL;
        return;
    end
    [~, idx] = min(abs(levels - configuredAL));
    aggLevel = double(levels(idx));
    return;
end
if policy == "most_robust"
    aggLevel = max(levels);
    return;
end
aggLevel = localSelectPDCCHAggregationLevel(levels, snr_dB);
end

function aggLevel = localSelectPDCCHAggregationLevel(levels, snr_dB)
snr_dB = double(snr_dB);
if ~isfinite(snr_dB)
    target = 4;
elseif snr_dB < 0
    target = 16;
elseif snr_dB < 5
    target = 8;
elseif snr_dB < 10
    target = 4;
elseif snr_dB < 15
    target = 2;
else
    target = 1;
end
[~, idx] = min(abs(double(levels(:)) - double(target)));
aggLevel = double(levels(idx));
end

function [T, grant] = localAnnotateGrantControlTrial(T, grant, cfg, direction)
if nargin < 3 || ~isstruct(cfg)
    cfg = struct();
end
if nargin < 4
    direction = sixgr.util.structGet(grant, "Direction", "DL");
end
if ~isstruct(grant)
    return;
end

direction = upper(strtrim(string(direction)));
binding = localResolvePDCCHGrantBinding(cfg, grant, direction, T);
grant.PDCCHGrantBindingRequired = logical(binding.Required);
grant.PDCCHGrantBindingOk = logical(binding.Ok);
grant.PDCCHGrantBindingStatus = char(string(binding.Status));
grant.PDCCHGrantBindingFailureCode = char(string(binding.FailureCode));
grant.PDCCHGrantDCIId = char(string(binding.DCIId));
grant.PDCCHGrantDCIFieldsHash = char(string(binding.DCIFieldsHash));
grant.PDCCHGrantFieldsHash = char(string(binding.GrantFieldsHash));
grant.PDCCHGrantSearchSpaceId = double(binding.SearchSpaceId);
grant.PDCCHGrantCORESETId = double(binding.CORESETId);
grant.PDCCHGrantAggregationLevel = double(binding.AggregationLevel);
grant.PDCCHGrantCandidateIndex = double(binding.CandidateIndex);
grant.PDCCHGrantDCIFormat = char(string(binding.DCIFormat));
grant.PDCCHGrantFirstCCE = NaN;
grant.PDCCHGrantNumCCE = NaN;
if binding.Ok && istable(T) && ~isempty(T)
    % Retain the received candidate, not the configured/transmitted candidate
    % or a fixed CORESET size. This same DCI owns later HARQ resource mapping.
    grant = sixgr.truth.bindReceivedPDCCHGrantContext(grant,T(end,:));
    binding.AggregationLevel = grant.PDCCHGrantAggregationLevel;
    binding.CandidateIndex = grant.PDCCHGrantCandidateIndex;
end

if ~(istable(T) && ~isempty(T))
    return;
end

heightT = height(T);
transmittedLayers = double(sixgr.util.structGet(grant, "NumLayers", sixgr.util.structGet(grant, "Layers", NaN)));
rankIndicator = double(sixgr.util.structGet(grant, "RIUsed", ...
    sixgr.util.structGet(grant, "RankIndicator", ...
    sixgr.util.structGet(grant, "RI", ...
    sixgr.util.structGet(grant, "Rank", transmittedLayers)))));
if ~(isfinite(rankIndicator) && rankIndicator >= 1) && isfinite(transmittedLayers) && transmittedLayers >= 1
    rankIndicator = double(transmittedLayers);
end
controlResourceValid = logical(binding.Ok) && ...
    isfinite(double(binding.SearchSpaceId)) && ...
    isfinite(double(binding.CORESETId)) && ...
    isfinite(double(binding.AggregationLevel)) && ...
    double(binding.AggregationLevel) > 0 && ...
    isfinite(double(binding.CandidateIndex));
annotations = {
    "PDCCHGatingActive", logical(sixgr.util.structGet(grant, "PDCCHGatingActive", false));
    "GrantControlState", string(sixgr.util.structGet(grant, "GrantControlState", "control_pending"));
    "ControlDecodeOk", logical(sixgr.util.structGet(grant, "ControlDecodeOk", false));
    "UEID", double(sixgr.util.structGet(grant, "UEIndex", NaN));
    "BaseStationID", double(sixgr.util.structGet(grant, "ServingCell", NaN));
    "GrantFrame", double(sixgr.util.structGet(grant, "Frame", NaN));
    "GrantSlot", double(sixgr.util.structGet(grant, "Slot", NaN));
    "ControlFrame", double(sixgr.util.structGet(grant, "ControlFrame", NaN));
    "ControlSlot", double(sixgr.util.structGet(grant, "ControlSlot", NaN));
    "ScheduledAbsoluteSlot", double(sixgr.util.structGet(grant, "ScheduledAbsoluteSlot", sixgr.util.structGet(grant, "Slot", NaN)));
    "GrantContextId", string(sixgr.util.structGet(grant, "GrantContextId", ""));
    "LinkedGrantId", string(sixgr.util.structGet(grant, "GrantContextId", ""));
    "LinkedPDSCHOrPUSCH", direction;
    "K2Slots", double(sixgr.util.structGet(grant, "K2Slots", NaN));
    "LastSuccessfulSRSSlot", double(sixgr.util.structGet(grant, "LastSuccessfulSRSSlot", NaN));
    "SRSAgeSlots", double(sixgr.util.structGet(grant, "SRSAgeSlots", NaN));
    "AllocatedPRBCount", double(numel(double(sixgr.util.structGet(grant, "PRBSet", []))));
    "PRBStart", double(localFirstFinite(double(sixgr.util.structGet(grant, "PRBSet", [])), NaN));
    "MCSIndex", double(sixgr.util.structGet(grant, "MCSIndex", NaN));
    "Layers", transmittedLayers;
    "Rank", transmittedLayers;
    "RankIndicator", rankIndicator;
    "GrantValid", logical(sixgr.util.structGet(grant, "GrantValid", false));
    "NegativeExpectedOk", logical(sixgr.util.structGet(grant, "NegativeExpectedOk", false));
    "ControlResourceValidity", controlResourceValid;
    "GrantBindingRequired", logical(binding.Required);
    "GrantBindingOk", logical(binding.Ok);
    "GrantBindingStatus", string(binding.Status);
    "GrantBindingFailureCode", string(binding.FailureCode);
    "GrantFieldsHash", string(binding.GrantFieldsHash);
    "DCIFieldsHash", string(binding.DCIFieldsHash);
    "DCIId", string(binding.DCIId);
    "GrantSearchSpaceId", double(binding.SearchSpaceId);
    "GrantCORESETId", double(binding.CORESETId);
    "AggregationLevel", double(binding.AggregationLevel);
    "CandidateIndex", double(binding.CandidateIndex);
    "DCIFormat", string(binding.DCIFormat);
    "PDCCHGrantBindingRequired", logical(binding.Required);
    "PDCCHGrantBindingOk", logical(binding.Ok);
    "PDCCHGrantBindingStatus", string(binding.Status);
    "PDCCHGrantBindingFailureCode", string(binding.FailureCode);
    "PDCCHGrantDCIId", string(binding.DCIId);
    "PDCCHGrantDCIFieldsHash", string(binding.DCIFieldsHash);
    "PDCCHGrantFieldsHash", string(binding.GrantFieldsHash);
    "PDCCHGrantSearchSpaceId", double(binding.SearchSpaceId);
    "PDCCHGrantCORESETId", double(binding.CORESETId);
    "PDCCHGrantAggregationLevel", double(binding.AggregationLevel);
    "PDCCHGrantCandidateIndex", double(binding.CandidateIndex);
    "PDCCHGrantDCIFormat", string(binding.DCIFormat)
    };
for i = 1:size(annotations, 1)
    name = char(annotations{i, 1});
    value = annotations{i, 2};
    if isstring(value) || ischar(value)
        token = string(value);
        if ~isscalar(token)
            token = token(1);
        end
        T.(name) = repmat(token, heightT, 1);
    elseif islogical(value)
        flag = logical(value);
        if ~isscalar(flag)
            flag = flag(1);
        end
        T.(name) = repmat(flag, heightT, 1);
    else
        numValue = double(value);
        if ~isscalar(numValue)
            numValue = localFirstFinite(numValue, NaN);
        end
        T.(name) = repmat(numValue, heightT, 1);
    end
end
end

function binding = localResolvePDCCHGrantBinding(cfg, grant, direction, T)
direction = upper(strtrim(string(direction)));
grantPayload = localGrantBindingPayloadFromGrant(grant, direction);
binding = struct( ...
    "Required", true, ...
    "Ok", false, ...
    "Status", "not_required", ...
    "FailureCode", "", ...
    "DCIId", "", ...
    "DCIFieldsHash", "", ...
    "GrantFieldsHash", localGrantBindingPayloadHash(grantPayload), ...
    "SearchSpaceId", localFirstFinite([ ...
        double(sixgr.util.structGet(grant, "SearchSpaceID", NaN)), ...
        double(sixgr.util.structGet(grant, "SearchSpaceId", NaN)), ...
        double(sixgr.util.structGet(grant, "PDCCHGrantSearchSpaceId", NaN))], NaN), ...
    "CORESETId", localFirstFinite([ ...
        double(sixgr.util.structGet(grant, "CORESETID", NaN)), ...
        double(sixgr.util.structGet(grant, "CORESETId", NaN)), ...
        double(sixgr.util.structGet(grant, "PDCCHGrantCORESETId", NaN))], NaN), ...
    "AggregationLevel", localFirstFinite([ ...
        double(sixgr.util.structGet(grant, "PDCCHAggregationLevel", NaN)), ...
        double(sixgr.util.structGet(grant, "PDCCHGrantAggregationLevel", NaN))], NaN), ...
    "CandidateIndex", double(sixgr.util.structGet(grant, "PDCCHGrantCandidateIndex", NaN)), ...
    "DCIFormat", char(string(grantPayload.DCIFormat)));
if ~binding.Required && ~(istable(T) && ~isempty(T))
    binding.Ok = true;
    return;
end

if ~(istable(T) && ~isempty(T))
    binding.Status = "missing_decoded_dci";
    binding.FailureCode = "decoded_dci_missing";
    return;
end

row = T(end, :);
decodedPayload = localGrantBindingPayloadFromDecodedRow(row, direction);
binding.DCIId = char(localTableText(row, ["DCIId","PayloadHash"], ""));
binding.DCIFieldsHash = char(localTableText(row, "DCIFieldsHash", ""));
binding.SearchSpaceId = localFirstFinite([binding.SearchSpaceId, localTableNumber(row, "SearchSpaceId", NaN)], NaN);
binding.CORESETId = localFirstFinite([binding.CORESETId, localTableNumber(row, "CORESETId", NaN)], NaN);
binding.AggregationLevel = localFirstFinite([binding.AggregationLevel, localTableNumber(row, "AggregationLevel", NaN)], NaN);
binding.CandidateIndex = localFirstFinite([binding.CandidateIndex, ...
    localTableNumber(row, ["CandidateIndex","PDCCHCandidateIndex"], NaN)], NaN);
binding.DCIFormat = char(localTableText(row, "DCIFormat", binding.DCIFormat));

failures = strings(0, 1);
if ~localTableLogical(row, "DCICrcPass", false)
    failures(end+1, 1) = "decoded_dci_crc_failed"; %#ok<AGROW>
end
if ~localTableLogical(row, "PDCCHPayloadMatch", false)
    failures(end+1, 1) = "decoded_dci_payload_mismatch"; %#ok<AGROW>
end
if strlength(strtrim(string(binding.DCIFieldsHash))) == 0
    failures(end+1, 1) = "decoded_dci_fields_hash_missing"; %#ok<AGROW>
end
if strlength(strtrim(string(binding.GrantFieldsHash))) == 0
    failures(end+1, 1) = "grant_fields_hash_missing"; %#ok<AGROW>
end
if ~localBindingNumbersMatch(decodedPayload.RNTI, grantPayload.RNTI)
    failures(end+1, 1) = "rnti_mismatch"; %#ok<AGROW>
end
if ~localBindingNumbersMatch(decodedPayload.HARQProcessId, grantPayload.HARQProcessId)
    failures(end+1, 1) = "harq_process_mismatch"; %#ok<AGROW>
end
if ~localBindingNumbersMatch(decodedPayload.PRBStart, grantPayload.PRBStart) || ...
        ~localBindingNumbersMatch(decodedPayload.AllocatedPRBCount, grantPayload.AllocatedPRBCount)
    failures(end+1, 1) = "prb_allocation_mismatch"; %#ok<AGROW>
end
if ~localBindingNumbersMatch(decodedPayload.SymbolStart, grantPayload.SymbolStart) || ...
        ~localBindingNumbersMatch(decodedPayload.NumSymbols, grantPayload.NumSymbols)
    failures(end+1, 1) = "symbol_allocation_mismatch"; %#ok<AGROW>
end
if ~localBindingNumbersMatch(decodedPayload.MCSIndex, grantPayload.MCSIndex)
    failures(end+1, 1) = "mcs_mismatch"; %#ok<AGROW>
end
if ~localBindingNumbersMatch(decodedPayload.RV, grantPayload.RV)
    failures(end+1, 1) = "rv_mismatch"; %#ok<AGROW>
end
if ~localBindingNumbersMatch(decodedPayload.NDI, grantPayload.NDI)
    failures(end+1, 1) = "ndi_mismatch"; %#ok<AGROW>
end
if ~localBindingNumbersMatch(decodedPayload.TimeDomainAssignmentIndex, grantPayload.TimeDomainAssignmentIndex)
    failures(end+1, 1) = "time_domain_assignment_mismatch"; %#ok<AGROW>
end
if ~localBindingTextsMatch(binding.DCIFormat, grantPayload.DCIFormat)
    failures(end+1, 1) = "dci_format_mismatch"; %#ok<AGROW>
end
observedSearchSpaceId = localTableNumber(row, "SearchSpaceId", NaN);
if ~(isfinite(observedSearchSpaceId) && isfinite(binding.SearchSpaceId) && ...
        double(observedSearchSpaceId) == double(binding.SearchSpaceId))
    failures(end+1, 1) = "search_space_mismatch"; %#ok<AGROW>
end
observedCORESETId = localTableNumber(row, "CORESETId", NaN);
if ~(isfinite(observedCORESETId) && isfinite(binding.CORESETId) && ...
        double(observedCORESETId) == double(binding.CORESETId))
    failures(end+1, 1) = "coreset_mismatch"; %#ok<AGROW>
end
if strlength(strtrim(string(binding.DCIFieldsHash))) > 0 && strlength(strtrim(string(binding.GrantFieldsHash))) > 0 && ...
        string(binding.DCIFieldsHash) ~= string(binding.GrantFieldsHash)
    failures(end+1, 1) = "dci_grant_fields_hash_mismatch"; %#ok<AGROW>
end

failures = unique(failures(strlength(strtrim(failures)) > 0), "stable");
binding.Ok = isempty(failures);
binding.Status = ternaryBinding(binding.Ok, "bound", "failed");
binding.FailureCode = char(strjoin(failures, "|"));
end

function payload = localGrantBindingPayloadFromGrant(grant, direction)
direction = upper(strtrim(string(direction)));
prbSet = double(sixgr.util.structGet(grant, "PRBSet", []));
prbSet = prbSet(isfinite(prbSet));
prbStart = localFirstFinite(prbSet, double(sixgr.util.structGet(grant, "PRBStart", NaN)));
if isempty(prbSet)
    prbCount = double(sixgr.util.structGet(grant, "AllocatedPRBCount", ...
        sixgr.util.structGet(grant, "PRBCount", NaN)));
else
    prbCount = double(numel(prbSet));
end
symbolAllocation = double(sixgr.util.structGet(grant, "SymbolAllocation", []));
symbolAllocation = symbolAllocation(isfinite(symbolAllocation));
if numel(symbolAllocation) >= 2
    symbolStart = double(symbolAllocation(1));
    numSymbols = double(symbolAllocation(2));
else
    symbolStart = double(sixgr.util.structGet(grant, "SymbolStart", NaN));
    numSymbols = double(sixgr.util.structGet(grant, "NumSymbols", NaN));
end
payload = struct( ...
    "Direction", char(direction), ...
    "DCIFormat", char(localResolvePDCCHGrantDCIFormat(grant, direction)), ...
    "RNTI", double(sixgr.util.structGet(grant, "RNTI", NaN)), ...
    "HARQProcessId", localFirstFinite([ ...
        double(sixgr.util.structGet(grant, "HARQ.HARQProcess", NaN)), ...
        double(sixgr.util.structGet(grant, "HARQ.HarqID", NaN)), ...
        double(sixgr.util.structGet(grant, "HARQProcessId", NaN))], NaN), ...
    "PRBStart", double(prbStart), ...
    "AllocatedPRBCount", double(prbCount), ...
    "SymbolStart", double(symbolStart), ...
    "NumSymbols", double(numSymbols), ...
    "TimeDomainAssignmentIndex", localFirstFinite([ ...
        double(sixgr.util.structGet(grant, "DCI.TimeDomainAssignmentIndex", NaN)), ...
        double(sixgr.util.structGet(grant, "TimeDomainResourceAssignmentIndex", NaN)), ...
        double(sixgr.util.structGet(grant, "TDRAIndex", NaN)), ...
        double(sixgr.util.structGet(grant, "TimeResourceAssignment", NaN))], NaN), ...
    "MCSIndex", localFirstFinite([ ...
        double(sixgr.util.structGet(grant, "MCSIndex", NaN)), ...
        double(sixgr.util.structGet(grant, "MCS", NaN))], NaN), ...
    "RV", localFirstFinite([ ...
        double(sixgr.util.structGet(grant, "HARQ.RV", NaN)), ...
        double(sixgr.util.structGet(grant, "RV", NaN))], NaN), ...
    "NDI", localFirstFinite([ ...
        double(sixgr.util.structGet(grant, "HARQ.NDI", NaN)), ...
        double(sixgr.util.structGet(grant, "NDI", NaN))], NaN));
end

function payload = localGrantBindingPayloadFromDecodedRow(row, direction)
payload = struct( ...
    "Direction", char(upper(strtrim(string(direction)))), ...
    "DCIFormat", char(localTableText(row, "DCIFormat", localResolvePDCCHGrantDCIFormat(struct(), direction))), ...
    "RNTI", double(localTableNumber(row, "PDCCHDCICrcRNTI", NaN)), ...
    "HARQProcessId", double(localTableNumber(row, "DecodedDCIHARQProcessId", NaN)), ...
    "PRBStart", double(localTableNumber(row, "DecodedDCIPRBStart", NaN)), ...
    "AllocatedPRBCount", double(localTableNumber(row, "DecodedDCIAllocatedPRBCount", NaN)), ...
    "SymbolStart", double(localTableNumber(row, "DecodedDCISymbolStart", NaN)), ...
    "NumSymbols", double(localTableNumber(row, "DecodedDCINumSymbols", NaN)), ...
    "TimeDomainAssignmentIndex", double(localTableNumber(row, "DecodedDCITimeDomainAssignmentIndex", NaN)), ...
    "MCSIndex", double(localTableNumber(row, "DecodedDCIMCSIndex", NaN)), ...
    "RV", double(localTableNumber(row, "DecodedDCIRV", NaN)), ...
    "NDI", double(localTableNumber(row, "DecodedDCINDI", NaN)));
end

function hash = localGrantBindingPayloadHash(payload)
hash = "";
if ~(isstruct(payload) && ~isempty(fieldnames(payload)))
    return;
end
try
    hash = char(sixgr.util.sha256Hex(uint8(unicode2native(char(jsonencode(orderfields(payload))), "UTF-8"))));
catch
    hash = "";
end
end

function tf = localBindingNumbersMatch(lhs, rhs)
lhs = localFirstFinite(lhs, NaN);
rhs = localFirstFinite(rhs, NaN);
tf = isfinite(lhs) && isfinite(rhs) && abs(double(lhs) - double(rhs)) < 1e-9;
end

function tf = localBindingTextsMatch(lhs, rhs)
lhs = strtrim(string(lhs));
rhs = strtrim(string(rhs));
tf = strlength(lhs) > 0 && strlength(rhs) > 0 && lhs == rhs;
end

function value = localTableText(row, names, defaultValue)
value = string(defaultValue);
if ~(istable(row) && height(row) >= 1)
    return;
end
names = string(names);
vars = string(row.Properties.VariableNames);
for ii = 1:numel(names)
    if any(vars == names(ii))
        token = string(row.(names(ii))(1));
        if strlength(strtrim(token)) > 0
            value = token;
            return;
        end
    end
end
end

function value = localTableNumber(row, names, defaultValue)
value = double(defaultValue);
if ~(istable(row) && height(row) >= 1)
    return;
end
names = string(names);
vars = string(row.Properties.VariableNames);
for ii = 1:numel(names)
    if any(vars == names(ii))
        raw = double(row.(names(ii))(1));
        if isfinite(raw)
            value = raw;
            return;
        end
    end
end
end

function tf = localTableLogical(row, name, defaultValue)
tf = logical(defaultValue);
if ~(istable(row) && height(row) >= 1)
    return;
end
vars = string(row.Properties.VariableNames);
if any(vars == string(name))
    raw = row.(string(name))(1);
    if islogical(raw)
        tf = logical(raw);
    elseif isnumeric(raw)
        tf = logical(raw ~= 0);
    end
end
end

function value = ternaryBinding(cond, ifTrue, ifFalse)
if cond
    value = string(ifTrue);
else
    value = string(ifFalse);
end
end

function value = localFirstFinite(vals, defaultValue)
vals = double(vals(:));
vals = vals(isfinite(vals));
if isempty(vals)
    value = double(defaultValue);
else
    value = double(vals(1));
end
end

function [lhs, rhs] = localHarmonizeStructArrays(lhs, rhs)
if ~isstruct(lhs)
    lhs = struct();
end
if ~isstruct(rhs)
    rhs = struct();
end
lhsFields = string(fieldnames(lhs));
rhsFields = string(fieldnames(rhs));
allFields = union(lhsFields, rhsFields, "stable");
for i = 1:numel(allFields)
    fieldName = char(allFields(i));
    if ~isfield(lhs, fieldName)
        [lhs(1:numel(lhs)).(fieldName)] = deal([]);
    end
    if ~isfield(rhs, fieldName)
        [rhs(1:numel(rhs)).(fieldName)] = deal([]);
    end
end
end

function availCCEs = localPDCCHAvailableCCEs(pdcch)
availCCEs = NaN;
if isempty(pdcch)
    return;
end
core = [];
try
    core = pdcch.CORESET;
catch
end
if isempty(core)
    return;
end
freqResources = localPDCCHScalar(core, "FrequencyResources", []);
duration = localPDCCHScalar(core, "Duration", NaN);
if isempty(freqResources) || ~isfinite(duration) || duration <= 0
    return;
end
numREG = 6 * sum(freqResources ~= 0) * duration;
availCCEs = floor(numREG / 6);
end

function value = localPDCCHScalar(obj, propName, defaultValue)
value = defaultValue;
if isempty(obj)
    return;
end
try
    value = obj.(propName);
catch
    return;
end
if isnumeric(value)
    value = double(value);
elseif islogical(value)
    value = double(value);
end
end

function value = localPDCCHScalarVector(obj, propName)
value = [];
if isempty(obj)
    return;
end
try
    value = obj.(propName);
catch
    value = [];
    return;
end
if isnumeric(value) || islogical(value)
    value = double(value(:).');
else
    value = [];
end
end

function firstCCE = localResolvePDCCHFirstCCE(cfg, tx, aggregationLevel, candidateIndex, rnti)
% Resolve the actual first CCE from the configured search-space equation.
% A candidate ordinal is not a CCE index; exporting candidateIndex-1 as a
% CCE silently corrupts the control-resource lineage.
firstCCE = NaN;
aggregationLevel = double(aggregationLevel);
candidateIndex = double(candidateIndex);
if ~(isscalar(aggregationLevel) && isfinite(aggregationLevel) && ...
        ismember(aggregationLevel, [1 2 4 8 16]) && ...
        isscalar(candidateIndex) && isfinite(candidateIndex) && ...
        candidateIndex >= 0 && candidateIndex == fix(candidateIndex))
    return;
end
% The resource generator's monitored RNTI owns its CCE recurrence. The DCI
% CRC RNTI argument is not an independent resource-map authority.
nCI = double(sixgr.util.structGet(cfg,"phy.pdcch.searchSpace.nCI",0));
assert(isscalar(nCI) && nCI==0,'sixgr:truth:UnsupportedPDCCHCarrierIndicator', ...
    'Toolbox-generated PDCCH resources support nCI=0; metadata must not describe another map.');
context = sixgr.phy.pdcch.resolveCandidateContext( ...
    tx.Carrier,tx.PDCCH,aggregationLevel,candidateIndex);
firstCCE = context.FirstCCE;
end

function value = localFiniteOrNaN(value)
value = double(value);
if ~(isscalar(value) && isfinite(value))
    value = NaN;
end
end

function tf = localHasFiniteNumericEvidence(value)
tf = false;
if isempty(value)
    return;
end
try
    vals = abs(double(value(:)));
    tf = any(isfinite(vals));
catch ME
    if prachRequired
        rethrow(ME);
    end
    tf = false;
end
end

function hash = localComplexSHA256(value)
hash = "";
if isempty(value)
    return;
end
try
    data = single([real(value(:)).'; imag(value(:)).']);
    hash = string(sixgr.rrc.asn1.asn1SHA256Hex(typecast(data(:), "uint8")));
catch
    hash = "";
end
end

function hash = localPDCCHResourceHash(pdcchInd, dmrsInd)
hash = "";
try
    payload = struct("PDCCHInd", double(pdcchInd(:).'), "DMRSInd", double(dmrsInd(:).'));
    hash = string(sixgr.rrc.asn1.asn1SHA256Hex(uint8(unicode2native(jsonencode(payload), "UTF-8"))));
catch
    hash = "";
end
end

function dciFormat = localResolvePDCCHGrantDCIFormat(source, direction)
dciFormat = string(sixgr.util.structGet(source, "DCI.Format", ...
    sixgr.util.structGet(source, "DCIFormat", "")));
dciFormat = strtrim(dciFormat);
if strlength(dciFormat) == 0
    direction = upper(strtrim(string(direction)));
    if direction == "UL"
        dciFormat = "0_0";
    else
        dciFormat = "1_0";
    end
end
try
    dciFormat = sixgr.phy.pdcch.normalizeDCIFormat(dciFormat);
catch
    % The contextual DCI decoder will fail closed for an unsupported token.
end
end

function decodedDci = localDecodeObservedPDCCHGrantDCI(rx, tx, dciFormat, grantContext, cfg)
decodedDci = struct();
if isfield(sixgr.util.structGet(cfg,'phy.pdcch.operatorControl',struct()),'connected_dci')
    if logical(sixgr.util.structGet(rx,'Ok',false))
        assert(string(rx.DCISelectionSource)=="receiver_installed_context_crc_and_semantic_parse" && ...
            isstruct(rx.DecodedDCI) && ~isempty(fieldnames(rx.DecodedDCI)) && ...
            isequal(int8(rx.DecodedDCI.Bits(:)),int8(rx.DCIBits(:))), ...
            'sixgr:truth:MissingReceiverOwnedDCI','Connected control requires the actual receiver-parsed payload.');
        decodedDci=rx.DecodedDCI;
    end
    return;
end
bits = int8(sixgr.util.structGet(rx, "DCIBits", int8([])));
if isempty(bits)
    return;
end
try
    contextData = sixgr.util.structGet(grantContext, "DCI.ContextData", struct());
    if isstruct(contextData) && isscalar(contextData) && isfield(contextData, "SpecRelease")
        dciContext = sixgr.phy.pdcch.DCIContext(contextData);
    elseif isstruct(grantContext) && ~isempty(fieldnames(grantContext))
        dciContext = sixgr.phy.pdcch.DCIContextFactory.fromScheduledGrant( ...
            cfg, grantContext, dciFormat);
    else
        dciContext = sixgr.phy.pdcch.DCIContext.fromLegacy( ...
            struct("NSizeGrid", double(tx.Carrier.NSizeGrid)), dciFormat);
    end
    decodedDci = sixgr.phy.pdcch.decodeDCIPayload(bits, dciFormat, dciContext);
catch
    decodedDci = struct();
end
end

function hash = localHashDecodedPDCCHGrantFields(decodedDci, rnti)
hash = "";
if ~(isstruct(decodedDci) && ~isempty(fieldnames(decodedDci)))
    return;
end
payload = struct( ...
    "Direction", char(string(sixgr.util.structGet(decodedDci, "Direction", ""))), ...
    "DCIFormat", char(string(sixgr.util.structGet(decodedDci, "Format", ""))), ...
    "RNTI", double(rnti), ...
    "HARQProcessId", double(sixgr.util.structGet(decodedDci, "Fields.harq_process", NaN)), ...
    "PRBStart", double(sixgr.util.structGet(decodedDci, "Fields.prb_start", NaN)), ...
    "AllocatedPRBCount", double(sixgr.util.structGet(decodedDci, "Fields.num_prb", NaN)), ...
    "SymbolStart", double(sixgr.util.structGet(decodedDci, "Fields.symbol_start", NaN)), ...
    "NumSymbols", double(sixgr.util.structGet(decodedDci, "Fields.num_symbols", NaN)), ...
    "TimeDomainAssignmentIndex", double(sixgr.util.structGet(decodedDci, ...
        "Fields.time_domain_assignment_index",sixgr.util.structGet(decodedDci,"Fields.time_resource_assignment",NaN))), ...
    "MCSIndex", double(sixgr.util.structGet(decodedDci, "Fields.mcs", NaN)), ...
    "RV", double(sixgr.util.structGet(decodedDci, "Fields.rv", NaN)), ...
    "NDI", double(sixgr.util.structGet(decodedDci, "Fields.ndi", NaN)));
hash = localGrantBindingPayloadHash(payload);
end

function T = localCollectPUCCHTrials(cfg, snr_dB, nTrials)
nTrials = max(1, round(double(nTrials)));
rows = repmat(localMakeLinkTrialRow(cfg, "UL", snr_dB, 1), nTrials, 1);
for k = 1:nTrials
    r = localMakeLinkTrialRow(cfg, "UL", snr_dB, k);
    r.Status = "FAIL";
    uci = int8(randi([0 1], 20, 1));
    try
        rnti = double(sixgr.util.structGet(cfg,"phy.rnti",NaN));
        if ~(isscalar(rnti) && isfinite(rnti))
            error("sixgr:phy:pucch:WrongRNTI", ...
                "Connected PUCCH campaign requires a configured finite RNTI.");
        end
        ue = struct("UEID",1,"RNTI",rnti,"ServingCell",0, ...
            "PUCCHCell",0,"ComponentCarrier",0,"ActiveULBWP",0);
        frame = struct("K1",1,"K1Source","configured_csi_timing", ...
            "PDSCHEndSlot",k-1,"TargetSlot",k,"DecodedPRI",0, ...
            "PRIFieldWidth",3,"PRIProvenance","configured_csi_resource", ...
            "FirstCCE",NaN,"NumCCE",NaN, ...
            "SlotSymbolOwnership","UUUUUUUUUUUUUU", ...
            "FlexibleResolutionProvided",false);
        connected = sixgr.phy.pucch.PUCCHConfigBuilder.connectedCSI( ...
            cfg,ue,uci,int8([]),frame);
        carrier = sixgr.phy.grid.makeCarrier(cfg);
        out = sixgr.link.runPUCCHWaveformTrial(cfg, ...
            "Carrier",carrier, ...
            "Assignment",connected.Assignment, ...
            "Report",connected.Report, ...
            "ReceiverContext",connected.ReceiverContext, ...
            "SNR_dB", snr_dB, ...
            "ChannelProfile",sixgr.channel.resolveConcreteProfile(cfg), ...
            "Seed",k);
        ok = logical(sixgr.util.structGet(out, "Ok", false)) && ~logical(sixgr.util.structGet(out, "Skipped", false));
        r.TBSize_bits = double(numel(uci));
        r.BitsCompared = double(sixgr.util.structGet(out, "BitsCompared", NaN));
        r.BitErrors = double(sixgr.util.structGet(out, "BitErrors", NaN));
        r.ExpectedBitCount = double(sixgr.util.structGet(out, "ExpectedBitCount", numel(uci)));
        r.DecodedBitCount = double(sixgr.util.structGet(out, "DecodedBitCount", NaN));
        r.UCIExpectedBitVector = string(sixgr.util.structGet(out, "UCIExpectedBitVector", ""));
        r.UCIDecodedBitVector = string(sixgr.util.structGet(out, "UCIDecodedBitVector", ""));
        r.UCIBitErrorVector = string(sixgr.util.structGet(out, "UCIBitErrorVector", ""));
        r.UCICodedBitCount = double(sixgr.util.structGet(out, "UCICodedBitCount", NaN));
        r.UCICRCBitCount = double(sixgr.util.structGet(out, "UCICRCBitCount", NaN));
        r.UCICRCApplicable = logical(sixgr.util.structGet(out, "UCICRCApplicable", false));
        r.CRCApplicable = logical(sixgr.util.structGet(out, "CRCApplicable", false));
        r.CRCOutcome = string(sixgr.util.structGet(out, "CRCOutcome", ternaryPUCCHCRCOutcome(r.CRCApplicable, ok)));
        r.UCIContentMatch = logical(sixgr.util.structGet(out, "UCIContentMatch", ok));
        r.DetectionOutcome = string(sixgr.util.structGet(out, "DetectionOutcome", ternaryPUCCHDetectionOutcome( ...
            logical(sixgr.util.structGet(out, "DetectionUsable", false)), r.UCIContentMatch)));
        if logical(r.CRCApplicable)
            r.CRCPass = double(ok);
        else
            r.CRCPass = NaN;
        end
        r.DetectionMetric = double(sixgr.util.structGet(out, "DetectionMetric", NaN));
        r.DetectionThreshold = double(sixgr.util.structGet(out, "DetectionThreshold", NaN));
        r.DetectionMetricStatus = string(sixgr.util.structGet(out, "DetectionMetricStatus", ""));
        r.DetectorPeakMetric = double(sixgr.util.structGet(out, "DetectorPeakMetric", NaN));
        r.DetectorNoiseFloor = double(sixgr.util.structGet(out, "DetectorNoiseFloor", NaN));
        r.DTXFlag = logical(sixgr.util.structGet(out, "DTXFlag", false));
        r.DTXReason = string(sixgr.util.structGet(out, "DTXReason", ""));
        r.ComputeLatency_ms = double(sixgr.util.structGet(out, "ComputeLatency_ms", NaN));
        r.DecodeLatency_ms = double(sixgr.util.structGet(out, "DecodeLatency_ms", NaN));
        r.AirInterfaceTTI_ms = double(sixgr.util.structGet(out, "AirInterfaceTTI_ms", NaN));
        r.AirInterfaceObservation_ms = double(sixgr.util.structGet(out, "AirInterfaceObservation_ms", r.AirInterfaceTTI_ms));
        r.ProcedureDelay_ms = double(sixgr.util.structGet(out, "ProcedureDelay_ms", 0));
        r.NoiseVariance = double(sixgr.util.structGet(out, "NoiseVariance", NaN));
        r.NoiseVarStatus = string(sixgr.util.structGet(out, "NoiseVarStatus", ""));
        r.NoiseVarSource = string(sixgr.util.structGet(out, "NoiseVarSource", ""));
        r.NoiseVarReason = string(sixgr.util.structGet(out, "NoiseVarReason", ""));
        r.NoiseVarStrictFailure = logical(sixgr.util.structGet(out, "NoiseVarStrictFailure", false));
        r.ReceiverUsable = logical(sixgr.util.structGet(out, "ReceiverUsable", false));
        r.DetectionAttempted = logical(sixgr.util.structGet(out, "DetectionAttempted", false));
        r.DetectionSuccess = logical(ok);
        r.DetectionUsable = logical(sixgr.util.structGet(out, "DetectionUsable", false));
        r.FailureReason = string(sixgr.util.structGet(out, "FailureReason", ""));
        r.ChannelEstimateAttempted = logical(sixgr.util.structGet(out, "ChannelEstimateAttempted", false));
        r.ChannelEstimateAvailable = logical(sixgr.util.structGet(out, "ChannelEstimateAvailable", false));
        r.ChannelEstimateSource = "nrPUCCHDMRS_nrChannelEstimate";
        r.ResourceExtractionAttempted = logical(sixgr.util.structGet(out, "ResourceExtractionAttempted", false));
        r.ResourceExtractionAvailable = logical(sixgr.util.structGet(out, "ResourceExtractionAvailable", false));
        r.EqualizationAttempted = logical(sixgr.util.structGet(out, "EqualizationAttempted", false));
        r.EqualizationAvailable = logical(sixgr.util.structGet(out, "EqualizationAvailable", false));
        r.ConfiguredSNR_dB = double(sixgr.util.structGet(out, "ConfiguredSNR_dB", snr_dB));
        r.AppliedAWGNSNR_dB = double(sixgr.util.structGet(out, "AppliedAWGNSNR_dB", NaN));
        r.DesiredSignalPowerBeforeNoise = double(sixgr.util.structGet(out, "DesiredSignalPowerBeforeNoise", NaN));
        r.CompositeSignalPowerBeforeNoise = double(sixgr.util.structGet(out, "CompositeSignalPowerBeforeNoise", NaN));
        r.AppliedNoiseSNR_dB = double(sixgr.util.structGet(out, "AppliedNoiseSNR_dB", NaN));
        r.NoiseVarianceSource = string(sixgr.util.structGet(out, "NoiseVarianceSource", ""));
        r.ReceiverHestSINR_dB = double(sixgr.util.structGet(out, "ReceiverHestSINR_dB", NaN));
        r.ReceiverHestSINRApplicable = logical(sixgr.util.structGet(out, "ReceiverHestSINRApplicable", false));
        r.ReceiverHestSINRSource = string(sixgr.util.structGet(out, "ReceiverHestSINRSource", ""));
        r.ReceiverHestSINRValueRole = string(sixgr.util.structGet(out, "ReceiverHestSINRValueRole", ""));
        r.ReceiverHestSINRValueStatus = string(sixgr.util.structGet(out, "ReceiverHestSINRValueStatus", ""));
        r.ReceiverHestSINRNAReason = string(sixgr.util.structGet(out, "ReceiverHestSINRNAReason", ""));
        r.PostEqSINR_dB = double(sixgr.util.structGet(out, "PostEqSINR_dB", NaN));
        r.PostEqSINRSource = string(sixgr.util.structGet(out, "PostEqSINRSource", ""));
        r.PostEqSINRValueRole = string(sixgr.util.structGet(out, "PostEqSINRValueRole", ""));
        r.PostEqSINRValueStatus = string(sixgr.util.structGet(out, "PostEqSINRValueStatus", ""));
        r.PostEqSINRNAReason = string(sixgr.util.structGet(out, "PostEqSINRNAReason", ""));
        r.PostEqSINRPerLayer_dB = localFormatNumericVector(sixgr.util.structGet(out, "PostEqSINRPerLayer_dB", ""));
        r.MeasuredTrialSINR_dB = double(sixgr.util.structGet(out, "MeasuredTrialSINR_dB", NaN));
        r.MeasuredTrialSINRSource = string(sixgr.util.structGet(out, "MeasuredTrialSINRSource", ""));
        r.MeasuredTrialSINRValueRole = string(sixgr.util.structGet(out, "MeasuredTrialSINRValueRole", ""));
        r.MeasuredTrialSINRValueStatus = string(sixgr.util.structGet(out, "MeasuredTrialSINRValueStatus", ""));
        r.MeasuredTrialSINRNAReason = string(sixgr.util.structGet(out, "MeasuredTrialSINRNAReason", ""));
        r.MeasuredSINR_dB = double(sixgr.util.structGet(out, "MeasuredTrialSINR_dB", NaN));
        r.SINRValueRole = string(sixgr.util.structGet(out, "SINRValueRole", ""));
        r.SINRSource = string(sixgr.util.structGet(out, "SINRSource", ""));
        r.SINRValueStatus = string(sixgr.util.structGet(out, "SINRValueStatus", ""));
        r.SINRValueDefinition = string(sixgr.util.structGet(out, "SINRValueDefinition", ""));
        r.WidebandCQI = double(sixgr.util.structGet(out, "WidebandCQI", NaN));
        r.RankIndicator = double(sixgr.util.structGet(out, "RankIndicator", NaN));
        r.PMI = double(sixgr.util.structGet(out, "PMI", NaN));
        r.CRI = double(sixgr.util.structGet(out, "CRI", NaN));
        r.ChannelGain_dB = double(sixgr.util.structGet(out, "ChannelGain_dB", NaN));
        r.ConditionNumber_dB = double(sixgr.util.structGet(out, "ConditionNumber_dB", NaN));
        r.NumRxAntennas = double(sixgr.util.structGet(out, "NumRxAntennas", NaN));
        r.NumTxPorts = double(sixgr.util.structGet(out, "NumTxPorts", NaN));
        r.RequestedFormat = double(sixgr.util.structGet(out, "RequestedFormat", NaN));
        r.ResolvedFormat = double(sixgr.util.structGet(out, "ResolvedFormat", NaN));
        r.FormatAdapted = logical(sixgr.util.structGet(out, "FormatAdapted", false));
        r.FormatAdaptationReason = string(sixgr.util.structGet(out, "FormatAdaptationReason", ""));
        r.ControlResourceValidity = logical(sixgr.util.structGet(out, "ControlResourceValidity", false));
        r.ControlResourceSource = "runtime_pucch_waveform_resource_mapping";
        r.PUCCHFormat = double(sixgr.util.structGet(out, "PUCCHFormat", r.ResolvedFormat));
        r.PUCCHResourceId = string(sixgr.util.structGet(out, "PUCCHResourceId", ""));
        r.PUCCHPRBSet = string(sixgr.util.structGet(out, "PUCCHPRBSet", ""));
        r.PUCCHPRBStart = double(sixgr.util.structGet(out, "PUCCHPRBStart", NaN));
        r.PUCCHPRBCount = double(sixgr.util.structGet(out, "PUCCHPRBCount", NaN));
        r.PUCCHSymbolStart = double(sixgr.util.structGet(out, "PUCCHSymbolStart", NaN));
        r.PUCCHNumSymbols = double(sixgr.util.structGet(out, "PUCCHNumSymbols", NaN));
        r.PUCCHRECount = double(sixgr.util.structGet(out, "PUCCHRECount", NaN));
        r.PUCCHDMRSRECount = double(sixgr.util.structGet(out, "PUCCHDMRSRECount", NaN));
        r.PUCCHExpectedBitCount = double(sixgr.util.structGet(out, "PUCCHExpectedBitCount", r.ExpectedBitCount));
        r.PUCCHDecodedBitCount = double(sixgr.util.structGet(out, "PUCCHDecodedBitCount", r.DecodedBitCount));
        r.PUCCHControlSINR_dB = double(sixgr.util.structGet(out, "PUCCHControlSINR_dB", NaN));
        r.PUCCHReceiverEvidenceSource = string(sixgr.util.structGet(out, "PUCCHReceiverEvidenceSource", ""));
        r.PUCCHGridHash = string(sixgr.util.structGet(out, "PUCCHGridHash", ""));
        r.PUCCHWaveformHash = string(sixgr.util.structGet(out, "PUCCHWaveformHash", ""));
        r.StrictReceiverEvidenceOk = logical(sixgr.util.structGet(out, "StrictReceiverEvidenceOk", false));
        r.StrictOk = logical(sixgr.util.structGet(out, "StrictOk", false));
        r.DecodeAttempted = true;
        r.DecodeUsable = logical(r.StrictOk);
        r.MeasurementAttempted = true;
        r.MeasurementUsable = isfinite(r.PUCCHControlSINR_dB) || ...
            (isfinite(r.ReceiverHestSINR_dB) && ...
            sixgr.util.isAcceptableSINRStatus(r.ReceiverHestSINRValueStatus));
        r.ReceiverUsable = logical(r.StrictReceiverEvidenceOk);
        r.TruthStatus = "real_pucch_waveform_uci_receiver_evidence";
        r.SourceClassification = "active_integrated";
        r.RuntimeMaterializationStatus = "active_integrated_pucch_waveform_uci_resource_receiver_evidence";
        r.RuntimeEvidenceSource = "sixgr.link.runPUCCHWaveformTrial";
        r.Crash = logical(sixgr.util.structGet(out, "Crash", false));
        r.Notes = string(sixgr.util.structGet(out, "Notes", ""));
        if logical(r.StrictOk)
            r.Status = "PASS";
        elseif ~logical(r.DetectionUsable)
            r.Status = "NA";
            r.CRCPass = NaN;
        elseif logical(sixgr.util.structGet(out, "Crash", false))
            r.Status = "CRASH";
        elseif logical(sixgr.util.structGet(out, "Skipped", false))
            r.Status = "NA";
        end
    catch ME
        r.Crash = true;
        r.CRCPass = 0;
        r.Status = "CRASH";
        r.Notes = string(ME.message);
    end
    rows(k) = r;
end
T = struct2table(rows);
end

function [T, chState, observedRET] = localCollectSRSTrials(cfg, snr_dB, nTrials, chState, trialOffset, receivedOutput)
if nargin < 6, receivedOutput=[]; end
assert(isempty(receivedOutput) || nTrials==1, ...
    'sixgr:truth:SharedSRSReducerMultiplicity','One actual SRS reception produces one canonical trial row.');
if nargin < 4
    chState = [];
end
if nargin < 5
    trialOffset = 0;
end
nTrials = max(1, round(double(nTrials)));
observedRET = table();
rows = repmat(localMakeLinkTrialRow(cfg, "UL", snr_dB, 1), nTrials, 1);
for k = 1:nTrials
    r = localMakeLinkTrialRow(cfg, "UL", snr_dB, k);
    r.Status = "FAIL";
    try
        srsArgs = {"SNR_dB", snr_dB, ...
            "TrialIndex", double(trialOffset) + k, "ChannelState", chState};
        if isfinite(double(trialOffset)) && double(trialOffset) > 0
            srsArgs = [srsArgs, {"SlotIndex", double(trialOffset)}]; %#ok<AGROW>
        end
        if isempty(receivedOutput)
            outSRS = sixgr.link.runSRSChannelEstimation(cfg, srsArgs{:});
        else
            outSRS = receivedOutput;
        end
        r.RuntimeEvidenceSource = "sixgr.link.runSRSChannelEstimation";
        observedRET = localAppendCompatTable(observedRET, ...
            sixgr.util.structGet(outSRS, "ObservedREAllocationTable", table()));
        chState = sixgr.util.structGet(outSRS, "ChannelState", chState);
        ok = logical(sixgr.util.structGet(outSRS, "Ok", false)) && ~logical(sixgr.util.structGet(outSRS, "Skipped", false));
        r.NMSE_dB = double(sixgr.util.structGet(outSRS, "NMSE_dB", NaN));
        r.NMSEReferenceSource = string(sixgr.util.structGet(outSRS, "NMSEReferenceSource", ""));
        r.TrueChannelOracleAvailable = logical(sixgr.util.structGet(outSRS, "TrueChannelOracleAvailable", false));
        r.TrueChannelNMSE_dB = double(sixgr.util.structGet(outSRS, "TrueChannelNMSE_dB", r.NMSE_dB));
        r.ChannelNMSEThreshold_dB = double(sixgr.util.structGet(outSRS, "ChannelNMSEThreshold_dB", NaN));
        r.PilotResidualNMSE_dB = double(sixgr.util.structGet(outSRS, "PilotResidualNMSE_dB", NaN));
        % Detection evidence is the actual received pilot correlation,
        % never the negative of an independent true-channel NMSE score.
        r.DetectionMetric = double(sixgr.util.structGet(outSRS, ...
            "ReceiveTiming.CorrelationPeakEnergy", NaN));
        r.DetectionMetricStatus = "unavailable_received_correlation_peak";
        if isfinite(r.DetectionMetric)
            r.DetectionMetricStatus = "received_reference_correlation_peak_energy";
        end
        r.InjectedDoppler_Hz = double(sixgr.util.structGet(outSRS, "InjectedDoppler_Hz", r.DopplerHz));
        r.EstimatedDopplerHz = double(sixgr.util.structGet(outSRS, "EstimatedDopplerHz", NaN));
        r.DopplerError_Hz = double(sixgr.util.structGet(outSRS, "DopplerError_Hz", NaN));
        r.QCLAccuracy = double(sixgr.util.structGet(outSRS, "QCLAccuracy", NaN));
        r.QCLMeasurementStatus = string(sixgr.util.structGet(outSRS,"QCLMeasurementStatus","unavailable"));
        r.InterpolationLoss_dB = double(sixgr.util.structGet(outSRS, "InterpolationLoss_dB", NaN));
        r.MismatchSensitivity_dB = double(sixgr.util.structGet(outSRS, "MismatchSensitivity_dB", NaN));
        r.ComputeLatency_ms = double(sixgr.util.structGet(outSRS, "ComputeLatency_ms", NaN));
        r.ProcedureDelay_ms = double(sixgr.util.structGet(outSRS, "ProcedureDelay_ms", NaN));
        r.AirInterfaceObservation_ms = double(sixgr.util.structGet(outSRS, "AirInterfaceObservation_ms", NaN));
        r.AcquisitionTime_ms = double(sixgr.util.structGet(outSRS, "AcquisitionTime_ms", NaN));
        r.TrackingFailureProbability = double(sixgr.util.structGet(outSRS, "TrackingFailure", NaN));
        r.NoiseVariance = double(sixgr.util.structGet(outSRS, "NoiseVariance", NaN));
        r.NoiseVarianceDomain = string(sixgr.util.structGet(outSRS,"NoiseVarianceDomain",""));
        r.InjectedSampleNoiseVariance = double(sixgr.util.structGet(outSRS,"InjectedSampleNoiseVariance",NaN));
        r.InjectedSampleNoiseVarianceDomain = string(sixgr.util.structGet(outSRS,"InjectedSampleNoiseVarianceDomain",""));
        r.NoiseVarStatus = string(sixgr.util.structGet(outSRS, "NoiseVarStatus", ""));
        r.NoiseVarSource = string(sixgr.util.structGet(outSRS, "NoiseVarSource", ""));
        r.NoiseVarReason = string(sixgr.util.structGet(outSRS, "NoiseVarReason", ""));
        r.NoiseVarStrictFailure = logical(sixgr.util.structGet(outSRS, "NoiseVarStrictFailure", false));
        r.NoiseOperatingMode = string(sixgr.util.structGet(outSRS, "NoiseOperatingMode", ""));
        r.NoisePowerSource = string(sixgr.util.structGet(outSRS, "NoisePowerSource", ""));
        r.ThermalNoisePower_dBm = double(sixgr.util.structGet(outSRS, "ThermalNoisePower_dBm", NaN));
        r.ServingRxPower_dBm = double(sixgr.util.structGet(outSRS, "ServingRxPower_dBm", NaN));
        r.ServingRxPowerSource = string(sixgr.util.structGet(outSRS, "ServingRxPowerSource", ""));
        r.PowerContextDirection = string(sixgr.util.structGet(outSRS, "PowerContextDirection", ""));
        r.PowerContextTotalTxPower_dBm = double(sixgr.util.structGet(outSRS, "PowerContextTotalTxPower_dBm", NaN));
        r.TxRFExecutionStatus = string(sixgr.util.structGet(outSRS, "TxRFExecutionStatus", ""));
        r.TxRFStageOrder = string(sixgr.util.structGet(outSRS, "TxRFStageOrder", ""));
        r.TxRFAppliedStageCount = double(sixgr.util.structGet(outSRS, "TxRFAppliedStageCount", NaN));
        r.CompositeReceiverFrontEndApplied = logical(sixgr.util.structGet(outSRS, "CompositeReceiverFrontEndApplied", false));
        r.CompositeReceiverFrontEndStatus = string(sixgr.util.structGet(outSRS, "CompositeReceiverFrontEndStatus", ""));
        r.ConfiguredSNR_dB = double(sixgr.util.structGet(outSRS, "ConfiguredSNR_dB", snr_dB));
        r.AppliedAWGNSNR_dB = double(sixgr.util.structGet(outSRS, "AppliedAWGNSNR_dB", NaN));
        r.DesiredSignalPowerBeforeNoise = double(sixgr.util.structGet(outSRS, "DesiredSignalPowerBeforeNoise", NaN));
        r.CompositeSignalPowerBeforeNoise = double(sixgr.util.structGet(outSRS, "CompositeSignalPowerBeforeNoise", NaN));
        r.AppliedNoiseSNR_dB = double(sixgr.util.structGet(outSRS, "AppliedNoiseSNR_dB", NaN));
        r.NoiseVarianceSource = string(sixgr.util.structGet(outSRS, "NoiseVarianceSource", ""));
        r.SignalEnergyPerOccupiedRE = double(sixgr.util.structGet( ...
            outSRS,"SignalEnergyPerOccupiedRE",NaN));
        r.ReferenceAWGNGridNoiseVariance = double(sixgr.util.structGet( ...
            outSRS,"ReferenceAWGNGridNoiseVariance",NaN));
        r.ReferenceAWGNSampleNoiseVariance = double(sixgr.util.structGet( ...
            outSRS,"ReferenceAWGNSampleNoiseVariance",NaN));
        r.SampleToGridNoiseVarianceGain = double(sixgr.util.structGet( ...
            outSRS,"SampleToGridNoiseVarianceGain",NaN));
        r.SNRReferencePlane = string(sixgr.util.structGet( ...
            outSRS,"SNRReferencePlane",""));
        r.WaveformPowerUsedForAWGN = logical(sixgr.util.structGet( ...
            outSRS,"WaveformPowerUsedForAWGN",false));
        r.ChannelModelApplied = string(sixgr.util.structGet(outSRS, "ChannelModelApplied", ""));
        r.ChannelFadingApplied = logical(sixgr.util.structGet(outSRS, "ChannelFadingApplied", false));
        r.AppliedLargeScaleGain_dB = double(sixgr.util.structGet(outSRS, "AppliedLargeScaleGain_dB", NaN));
        r.AppliedLargeScaleLoss_dB = double(sixgr.util.structGet(outSRS, "AppliedLargeScaleLoss_dB", NaN));
        r.AppliedBasePathloss_dB = double(sixgr.util.structGet(outSRS, "AppliedBasePathloss_dB", NaN));
        r.AppliedPathloss_dB = double(sixgr.util.structGet(outSRS, "AppliedPathloss_dB", NaN));
        r.AppliedShadowFading_dB = double(sixgr.util.structGet(outSRS, "AppliedShadowFading_dB", NaN));
        r.AppliedO2I_dB = double(sixgr.util.structGet(outSRS, "AppliedO2I_dB", NaN));
        r.AppliedLargeScaleGainSource = string(sixgr.util.structGet(outSRS, "AppliedLargeScaleGainSource", ""));
        r.InjectedCFO_Hz = double(sixgr.util.structGet(outSRS, "InjectedCFO_Hz", NaN));
        r.InjectedTimingOffset_samples = double(sixgr.util.structGet(outSRS, "InjectedTimingOffset_samples", NaN));
        r.DetectionAttempted = logical(sixgr.util.structGet(outSRS, "DetectionAttempted", false));
        r.DetectionSuccess = logical(sixgr.util.structGet(outSRS, "DetectionSuccess", false));
        r.DetectionUsable = logical(sixgr.util.structGet(outSRS, "DetectionUsable", false));
        r.ResourceExtractionAttempted = logical(sixgr.util.structGet(outSRS, "ResourceExtractionAttempted", false));
        r.ResourceExtractionAvailable = logical(sixgr.util.structGet(outSRS, "ResourceExtractionAvailable", false));
        r.ChannelEstimateAttempted = logical(sixgr.util.structGet(outSRS, "ChannelEstimateAttempted", false));
        r.ChannelEstimateAvailable = logical(sixgr.util.structGet(outSRS, "ChannelEstimateAvailable", ...
            sixgr.util.structGet(outSRS, "SRSChannelEstimateAvailable", false)));
        r.SRSChannelEstimateAvailable = logical(sixgr.util.structGet(outSRS, "SRSChannelEstimateAvailable", r.ChannelEstimateAvailable));
        r.StrictReceiverEvidenceOk = logical(sixgr.util.structGet(outSRS, "StrictReceiverEvidenceOk", false));
        r.SRSRuntimeEvidenceUsable = logical(sixgr.util.structGet(outSRS, "SRSRuntimeEvidenceUsable", false));
        r.StrictOk = logical(sixgr.util.structGet(outSRS, "StrictOk", false));
        r.ReceiverUsable = logical(r.StrictReceiverEvidenceOk);
        r.DecodeUsable = logical(r.StrictOk);
        r.MeasurementAttempted = logical(sixgr.util.structGet(outSRS, "MeasurementAttempted", false));
        r.MeasurementUsable = logical(sixgr.util.structGet(outSRS, "MeasurementUsable", false));
        r.FailureReason = string(sixgr.util.structGet(outSRS, "FailureReason", ""));
        r = sixgr.truth.bindReferenceSignalSINREvidence(r,outSRS,"SRS");
        r.PUSCHSchedulingSINRAnchor_dB = double(sixgr.util.structGet( ...
            outSRS, "PUSCHSchedulingSINRAnchor_dB", NaN));
        r.PUSCHSchedulingSINRAnchorSource = string(sixgr.util.structGet( ...
            outSRS, "PUSCHSchedulingSINRAnchorSource", ""));
        r.PUSCHSchedulingSINRAnchorPowerReferencePlane = string(sixgr.util.structGet( ...
            outSRS, "PUSCHSchedulingSINRAnchorPowerReferencePlane", ""));
        r.PUSCHSchedulingSINRAnchorValueStatus = string(sixgr.util.structGet( ...
            outSRS, "PUSCHSchedulingSINRAnchorValueStatus", "NOT_AVAILABLE"));
        r.WidebandCQI = double(sixgr.util.structGet(outSRS, "CQI", NaN));
        r.CQIDerivedMCS = double(sixgr.util.structGet(outSRS, "MCSIndex", NaN));
        r.CQIDerivedModulation = string(sixgr.util.structGet(outSRS, "Modulation", ""));
        r.CQIDerivedTargetCodeRate = double(sixgr.util.structGet(outSRS, "TargetCodeRate", NaN));
        r.RankEstimate = double(sixgr.util.structGet(outSRS, "RankEstimate", NaN));
        r.PredictedPUSCHPostEqSINRPerLayer_dB = localFormatNumericVector( ...
            sixgr.util.structGet(outSRS, "PredictedPUSCHPostEqSINRPerLayer_dB", []));
        r.PredictedPUSCHMinimumLayerSINR_dB = double(sixgr.util.structGet( ...
            outSRS, "PredictedPUSCHMinimumLayerSINR_dB", NaN));
        r.PredictedPUSCHWidebandMeanSINR_dB = double(sixgr.util.structGet( ...
            outSRS, "PredictedPUSCHWidebandMeanSINR_dB", NaN));
        r.PredictedPUSCHPostEqSINRSource = string(sixgr.util.structGet( ...
            outSRS, "PredictedPUSCHPostEqSINRSource", ""));
        r.PredictedPUSCHPostEqSINRValueRole = string(sixgr.util.structGet( ...
            outSRS, "PredictedPUSCHPostEqSINRValueRole", ""));
        r.PredictedPUSCHPostEqSINRValueStatus = string(sixgr.util.structGet( ...
            outSRS, "PredictedPUSCHPostEqSINRValueStatus", "NOT_AVAILABLE"));
        r.PredictedPUSCHPostEqSINRCalibrationOffset_dB = double(sixgr.util.structGet( ...
            outSRS, "PredictedPUSCHPostEqSINRCalibrationOffset_dB", NaN));
        r.PredictedPUSCHPostEqSINRAnchor_dB = double(sixgr.util.structGet( ...
            outSRS, "PredictedPUSCHPostEqSINRAnchor_dB", NaN));
        r.PredictedPUSCHPostEqSINRAnchorSource = string(sixgr.util.structGet( ...
            outSRS, "PredictedPUSCHPostEqSINRAnchorSource", ""));
        r.PredictedPUSCHPostEqSINRPowerReferencePlane = string(sixgr.util.structGet( ...
            outSRS, "PredictedPUSCHPostEqSINRPowerReferencePlane", ""));
        r.SRSOccupiedPRBCount = double(sixgr.util.structGet(outSRS, "SRSOccupiedPRBCount", NaN));
        r.SRSCarrierPRBCount = double(sixgr.util.structGet(outSRS, "SRSCarrierPRBCount", NaN));
        r.SRSBandwidthFraction = double(sixgr.util.structGet(outSRS, "SRSBandwidthFraction", NaN));
        r.SRSFrequencyPRBStart = double(sixgr.util.structGet(outSRS, "SRSFrequencyPRBStart", NaN));
        r.SRSFrequencyPRBEnd = double(sixgr.util.structGet(outSRS, "SRSFrequencyPRBEnd", NaN));
        r.SRSBandwidthCoverageStatus = string(sixgr.util.structGet(outSRS, "SRSBandwidthCoverageStatus", ""));
        r.SpatialSignatureToken = string(sixgr.util.structGet(outSRS, "SpatialSignatureToken", ""));
        r.SpatialSignatureSHA256 = string(sixgr.util.structGet(outSRS, "SpatialSignatureSHA256", ""));
        r.SpatialSignatureRows = double(sixgr.util.structGet(outSRS, "SpatialSignatureRows", NaN));
        r.SpatialSignatureColumns = double(sixgr.util.structGet(outSRS, "SpatialSignatureColumns", NaN));
        r.SpatialSignatureSource = string(sixgr.util.structGet(outSRS, "SpatialSignatureSource", ""));
        r.SpatialSignatureRawRank = double(sixgr.util.structGet(outSRS, "SpatialSignatureRawRank", NaN));
        r.SpatialSignatureRetainedRank = double(sixgr.util.structGet(outSRS, "SpatialSignatureRetainedRank", NaN));
        r.SpatialSignatureDetectionThreshold = double(sixgr.util.structGet(outSRS, "SpatialSignatureDetectionThreshold", NaN));
        r.SpatialSignatureNoiseVariance = double(sixgr.util.structGet(outSRS, "SpatialSignatureNoiseVariance", NaN));
        r.SpatialSignatureNoiseMargin_dB = double(sixgr.util.structGet(outSRS, "SpatialSignatureNoiseMargin_dB", NaN));
        r.SpatialSignatureSnapshotCount = double(sixgr.util.structGet(outSRS, "SpatialSignatureSnapshotCount", NaN));
        r.SpatialSignatureReductionMode = string(sixgr.util.structGet(outSRS, "SpatialSignatureReductionMode", ""));
        r.RankIndicator = double(sixgr.util.structGet(outSRS, "RIEstimate", outSRS.RankEstimate));
        r.PMI = double(sixgr.util.structGet(outSRS, "TPMIEstimate", NaN));
        r.ConditionNumber_dB = double(sixgr.util.structGet(outSRS, "SRSConditionNumber_dB", r.ConditionNumber_dB));
        r.RuntimeIntegrationMode = "coupled_slot_runtime";
        r.RuntimeTransportMode = "srs_tx_power_rf_runtime_channel_noise_rx_rf_srs_rx";
        r.RuntimeStageWaveformsRequired = true;
        r.RuntimeStageWaveformsUsed = true;
        r.RuntimeSelfLoopWaveformsUsed = false;
        r.RuntimeChannelStateUsed = logical(sixgr.util.structGet(outSRS, "RuntimeChannelStateUsed", false));
        r.RuntimeChannelLinkKeys = string(sixgr.util.structGet(outSRS, "RuntimeChannelLinkKeys", ""));
        r.RuntimeNoiseApplied = logical(sixgr.util.structGet(outSRS, "RuntimeNoiseApplied", false));
        r.RuntimeNoiseVarianceMean = double(sixgr.util.structGet(outSRS, "RuntimeNoiseVarianceMean", NaN));
        r.RuntimeStageCount = double(sixgr.util.structGet(outSRS, "RuntimeStageCount", 5));
        r.CRCPass = NaN;
        if ok
            r.Status = "PASS";
        elseif logical(sixgr.util.structGet(outSRS, "Skipped", false))
            r.Status = "NA";
        else
            r.Status = "FAIL";
            if strlength(strtrim(string(r.FailureReason))) == 0
                r.FailureReason = "srs_runtime_evidence_incomplete";
            end
        end
        r.Notes = string(sixgr.util.structGet(outSRS, "Notes", ""));
    catch ME
        r.Crash = true;
        r.CRCPass = NaN;
        r.Status = "CRASH";
        r.Notes = string(ME.message);
    end
    rows(k) = r;
end
T = struct2table(rows);
end

function [state, T] = localCollectCoupledSRSTrials(state, cfg, ueIdx, snr_dB, slotIdx)
% Bind causal SRS to the exact UL runtime channel later used by PUSCH.
% Apply the same per-UE geometry, power-reference and physical-antenna
% context used by ordinary UL grants.  The runtime channel handle alone is
% not a link budget: TS 38.213 SRS power control also requires the measured
% serving-link pathloss and YAML-owned power-control parameters.
[cfgU, state] = sixgr.truth.CoupledTruthRuntime.applyUserContext( ...
    cfg, state, ueIdx, "UL");
if sixgr.channel.ChannelFactory.requiresRuntimeChannelState(cfgU)
    [state, chState] = ...
        sixgr.truth.CoupledTruthRuntime.acquireRuntimeChannelStateForControl( ...
        state, cfgU, ueIdx, "UL");
    [T, chState, observedRET] = localCollectSRSTrials(cfgU, snr_dB, 1, chState, slotIdx);
    state.ObservedREAllocationTable = localAppendObservedREAllocation( ...
        sixgr.util.structGet(state, "ObservedREAllocationTable", table()), ...
        observedRET);
    state = sixgr.truth.CoupledTruthRuntime.commitRuntimeChannelState(state, chState);
    if ~isfield(state, "SRSChannelStateByUE") || numel(state.SRSChannelStateByUE) < ueIdx
        state.SRSChannelStateByUE{ueIdx, 1} = [];
    end
    % Retain only an identity/evidence mirror for compatibility.  The
    % authoritative mutable channel state lives in RuntimeChannelStates.
    state.SRSChannelStateByUE{ueIdx, 1} = chState;
    return;
end
if ~isfield(state, "SRSChannelStateByUE") || numel(state.SRSChannelStateByUE) < ueIdx
    state.SRSChannelStateByUE{ueIdx, 1} = [];
end
[T, chState, observedRET] = localCollectSRSTrials( ...
    cfgU, snr_dB, 1, state.SRSChannelStateByUE{ueIdx}, slotIdx);
state.ObservedREAllocationTable = localAppendObservedREAllocation( ...
    sixgr.util.structGet(state, "ObservedREAllocationTable", table()), ...
    observedRET);
state.SRSChannelStateByUE{ueIdx, 1} = chState;
end

function [T,chState,observedRET] = localCollectTRSTrials(cfg,snr_dB,nTrials,chState,receivedOut)
if nargin < 4 || ~isstruct(chState)
    chState = struct();
end
if nargin<5, receivedOut=struct(); end
observedRET = table();
if ~logical(sixgr.util.structGet(cfg, "phy.trs.enable", false))
    T = localEmptyLinkTrialTable(0);
    return;
end
nTrials = max(1, round(double(nTrials)));
rows = repmat(localMakeLinkTrialRow(cfg, "DL", snr_dB, 1), nTrials, 1);
for k = 1:nTrials
    r = localMakeLinkTrialRow(cfg, "DL", snr_dB, k);
    r.Status = "FAIL";
    try
        if isempty(fieldnames(receivedOut))
        out = sixgr.link.runTRSTracking(cfg,"SNR_dB",snr_dB, ...
            "ChannelState",chState,"RuntimeSlot", ...
            sixgr.util.structGet(cfg,"lls6g.userContext.RuntimeCurrentSlot",[]));
        else
            if nTrials~=1, error('sixgr:truth:ReceivedTRSTrialCount','One observation produces one TRS trial.'); end
            out=receivedOut;
        end
        r.ObservationStartSample = double(sixgr.util.structGet(out,"ObservationStartSample",NaN));
        r.ObservationEndSampleExclusive = double(sixgr.util.structGet(out,"ObservationEndSampleExclusive",NaN));
        r.ObservationSampleRateHz = double(sixgr.util.structGet(out,"ObservationSampleRateHz",NaN));
        r.ObservationCompletionTime_s = double(sixgr.util.structGet(out,"ObservationCompletionTime_s",NaN));
        r.ObservationCoverageSource = string(sixgr.util.structGet(out,"ObservationCoverageSource",""));
        observedRET = localAppendCompatTable(observedRET, ...
            sixgr.util.structGet(out, "ObservedREAllocationTable", table()));
        chState = sixgr.util.structGet(out,"ChannelState",chState);
        ok = logical(sixgr.util.structGet(out, "Ok", false)) && ~logical(sixgr.util.structGet(out, "Skipped", false));
        r.CRCPass = NaN;
        r.NMSE_dB = double(sixgr.util.structGet(out, "NMSE_dB", NaN));
        r.NMSEScoringAvailable = logical(sixgr.util.structGet(out,'NMSEScoringAvailable',false));
        r.NMSEReferenceSource = string(sixgr.util.structGet(out,'NMSEReferenceSource',"unavailable"));
        r.TrueChannelNMSE_dB = r.NMSE_dB;
        r.ChannelNMSEComparedComplexValues = double(sixgr.util.structGet(out,'ChannelNMSEComparedComplexValues',0));
        r.ChannelNMSEReferencePlane = string(sixgr.util.structGet(out,'ChannelNMSEReferencePlane',"unavailable"));
        r.ChannelNMSEReferenceIncludesRFImpairments = double(sixgr.util.structGet(out,'ChannelNMSEReferenceIncludesRFImpairments',NaN));
        r.QCLMeasurementStatus = string(sixgr.util.structGet(out,'QCLMeasurementStatus',"unavailable"));
        r.DetectionMetric = double(sixgr.util.structGet(out, "DetectionMetric", NaN));
        r.DetectionThreshold = double(sixgr.util.structGet(out, "DetectionThreshold", NaN));
        r.ResourceCoverageRatio = double(sixgr.util.structGet(out, "ResourceCoverageRatio", NaN));
        r.MinCoverageRatio = double(sixgr.util.structGet(out, "MinCoverageRatio", NaN));
        r.DetectionAttempted = logical(sixgr.util.structGet(out, "DetectionAttempted", false));
        r.DetectionSuccess = logical(sixgr.util.structGet(out, "DetectionSuccess", false));
        r.DetectionUsable = logical(r.DetectionAttempted) && logical(r.DetectionSuccess) && isfinite(r.DetectionMetric);
        r.ResourceExtractionAttempted = logical(sixgr.util.structGet(out, "ResourceExtractionAttempted", false));
        r.ResourceExtractionAvailable = logical(sixgr.util.structGet(out, "ResourceExtractionAvailable", false));
        r.MeasurementAttempted = logical(sixgr.util.structGet(out, "ChannelEstimationAttempted", false));
        r.MeasurementUsable = logical(sixgr.util.structGet(out,"TRSRuntimeEvidenceUsable",false));
        r.InjectedDoppler_Hz = double(sixgr.util.structGet(out, "InjectedDoppler_Hz", NaN));
        r.PhaseTrackingError_deg = double(sixgr.util.structGet(out, "PhaseError_deg", NaN));
        r.EstimatedDopplerHz = double(sixgr.util.structGet(out, "EstimatedDoppler_Hz", NaN));
        r.DopplerError_Hz = double(sixgr.util.structGet(out, "DopplerError_Hz", NaN));
        if ~isfinite(r.DopplerError_Hz) && isfinite(r.EstimatedDopplerHz) && isfinite(r.InjectedDoppler_Hz)
            r.DopplerError_Hz = r.EstimatedDopplerHz - r.InjectedDoppler_Hz;
        end
        r.QCLAccuracy = double(sixgr.util.structGet(out, "QCLAccuracy", NaN));
        r.InterpolationLoss_dB = double(sixgr.util.structGet(out, "InterpolationLoss_dB", NaN));
        r.MismatchSensitivity_dB = double(sixgr.util.structGet(out, "MismatchSensitivity_dB", NaN));
        r.TrackingEstimateSource = string(sixgr.util.structGet(out, "TrackingEstimateSource", ""));
        r.ChannelModel = char(string(sixgr.util.structGet(out, "ChannelModel", r.ChannelModel)));
        r.ChannelModelApplied = string(sixgr.util.structGet(out, "ChannelModelApplied", r.ChannelModelApplied));
        r.ChannelFadingApplied = logical(sixgr.util.structGet(out, "ChannelFadingApplied", r.ChannelFadingApplied));
        r.AppliedAWGNSNR_dB = double(sixgr.util.structGet(out, "AppliedAWGNSNR_dB", NaN));
        r.DesiredSignalPowerBeforeNoise = double(sixgr.util.structGet(out, "DesiredSignalPowerBeforeNoise", NaN));
        r.CompositeSignalPowerBeforeNoise = double(sixgr.util.structGet(out, "CompositeSignalPowerBeforeNoise", NaN));
        r.AppliedNoiseSNR_dB = double(sixgr.util.structGet(out, "AppliedNoiseSNR_dB", NaN));
        r.NoiseVarianceSource = string(sixgr.util.structGet(out, "NoiseVarianceSource", ""));
        r = sixgr.truth.bindTRSFrequencyEvidence(r,out);
        r.InjectedTimingOffset_samples = double(sixgr.util.structGet(out, "InjectedTimingOffset_samples", r.InjectedTimingOffset_samples));
        r.TrueTimingOffset_samples = double(sixgr.util.structGet(out, "TrueTimingOffset_samples", r.InjectedTimingOffset_samples));
        r.EstimatedTimingOffset_PreCorrection_samples = double(sixgr.util.structGet(out, "EstimatedTimingOffset_samples", NaN));
        r.EstimatedTimingOffset_samples = double(r.EstimatedTimingOffset_PreCorrection_samples);
        r.TimingEstimate_samples = double(r.EstimatedTimingOffset_PreCorrection_samples);
        r.TRSTimingEstimate_samples = double(r.EstimatedTimingOffset_PreCorrection_samples);
        r.TimingError_samples = double(sixgr.util.structGet(out, "TimingError_samples", NaN));
        r.TimingTrackingAttempted = logical(sixgr.util.structGet(out, "TimingTrackingAttempted", false));
        r.TRSTimingEstimateAvailable = logical(sixgr.util.structGet(out, "TRSTimingEstimateAvailable", false));
        r.TRSTimingEstimateUsable = logical(sixgr.util.structGet(out, "TRSTimingEstimateUsable", false));
        r.FrequencyTrackingAttempted = logical(sixgr.util.structGet(out, "FrequencyTrackingAttempted", false));
        r.TRSCFOEstimateUsable = logical(sixgr.util.structGet(out, "TRSCFOEstimateUsable", false));
        r.ChannelEstimationAttempted = logical(sixgr.util.structGet(out, "ChannelEstimationAttempted", false));
        r.TRSChannelEstimateAvailable = logical(sixgr.util.structGet(out, "TRSChannelEstimateAvailable", false));
        r.ChannelEstimateAttempted = logical(sixgr.util.structGet(out, "ChannelEstimateAttempted", r.ChannelEstimationAttempted));
        r.ChannelEstimateAvailable = logical(sixgr.util.structGet(out, "ChannelEstimateAvailable", r.TRSChannelEstimateAvailable));
        r.ChannelEstimator = string(sixgr.util.structGet(out, "ChannelEstimator", ""));
        r.ChannelEstimateDimensions = string(sixgr.util.structGet(out, "HestDimensions", ""));
        r.ChannelEstimateRxPorts = double(sixgr.util.structGet(out, "HestRxPorts", NaN));
        r.ChannelEstimateTxPorts = double(sixgr.util.structGet(out, "HestTxPorts", NaN));
        r.MeasuredTrialSINR_dB = double(sixgr.util.structGet(out, "MeasuredTrialSINR_dB", NaN));
        r.MeasuredTrialSINRSource = string(sixgr.util.structGet(out, "MeasuredTrialSINRSource", ""));
        r.MeasuredTrialSINRValueRole = string(sixgr.util.structGet(out, "MeasuredTrialSINRValueRole", ""));
        r.MeasuredTrialSINRValueStatus = string(sixgr.util.structGet(out, "MeasuredTrialSINRValueStatus", ""));
        r.MeasuredTrialSINRNAReason = string(sixgr.util.structGet(out, "MeasuredTrialSINRNAReason", ""));
        r = sixgr.truth.bindReferenceSignalSINREvidence(r,out,"TRS");
        r.DesiredPilotPower = double(sixgr.util.structGet(out, "DesiredPilotPower", NaN));
        r.ResidualPilotPower = double(sixgr.util.structGet(out, "ResidualPilotPower", NaN));
        r.TRSRuntimeEvidenceUsable = logical(sixgr.util.structGet(out, "TRSRuntimeEvidenceUsable", false));
        r.StrictOk = logical(sixgr.util.structGet(out, "StrictOk", false));
        r.ComputeLatency_ms = double(sixgr.util.structGet(out, "ComputeLatency_ms", NaN));
        r.ProcedureDelay_ms = double(sixgr.util.structGet(out, "ProcedureDelay_ms", NaN));
        r.AirInterfaceObservation_ms = double(sixgr.util.structGet(out, "AirInterfaceObservation_ms", NaN));
        r.AcquisitionTime_ms = double(sixgr.util.structGet(out, "AcquisitionTime_ms", NaN));
        r.TrackingFailureProbability = double(sixgr.util.structGet(out, "TrackingFailure", NaN));
        r.NoiseVariance = double(sixgr.util.structGet(out, "NoiseVariance", r.NoiseVariance));
        r.TxRFExecutionStatus = string(sixgr.util.structGet(out, "TxRFExecutionStatus", ""));
        r.TxRFStageOrder = string(sixgr.util.structGet(out, "TxRFStageOrder", ""));
        r.TxRFAppliedStageCount = double(sixgr.util.structGet(out, "TxRFAppliedStageCount", NaN));
        r.CompositeReceiverFrontEndApplied = logical(sixgr.util.structGet(out, "CompositeReceiverFrontEndApplied", false));
        r.CompositeReceiverFrontEndStatus = string(sixgr.util.structGet(out, "CompositeReceiverFrontEndStatus", ""));
        r.PowerNormalizationPolicy = string(sixgr.util.structGet(out, "PowerNormalizationPolicy", ""));
        r.PowerNormalizationSource = string(sixgr.util.structGet(out, "PowerNormalizationSource", ""));
        r.PowerNormalizationGridSource = string(sixgr.util.structGet(out, "PowerNormalizationGridSource", ""));
        r.PowerNormalizationGridSubcarrierCount = double(sixgr.util.structGet(out, "PowerNormalizationGridSubcarrierCount", NaN));
        r.PowerNormalizationGridActiveSymbolCount = double(sixgr.util.structGet(out, "PowerNormalizationGridActiveSymbolCount", NaN));
        r.PowerNormalizationGridMeanEnergyPerRE = double(sixgr.util.structGet(out, "PowerNormalizationGridMeanEnergyPerRE", NaN));
        r.FullBWPActivityFactor = double(sixgr.util.structGet(out, "FullBWPActivityFactor", NaN));
        r.ReferenceInputPower_dBm = double(sixgr.util.structGet(out, "ReferenceInputPower_dBm", NaN));
        r.ReferenceOutputPower_dBm = double(sixgr.util.structGet(out, "PowerReferenceOutput_dBm", NaN));
        r.ActualEmittedPower_dBm = double(sixgr.util.structGet(out, "ActualEmittedPower_dBm", NaN));
        r.ActualEmittedPowerBackoffFromBudget_dB = double(sixgr.util.structGet(out, "ActualEmittedPowerBackoffFromBudget_dB", NaN));
        r.PowerClosureError_dB = double(sixgr.util.structGet(out, "PowerClosureError_dB", NaN));
        r.PowerConversionEquation = string(sixgr.util.structGet(out, "PowerConversionEquation", ""));
        r.RuntimeIntegrationMode = "coupled_slot_runtime";
        r.RuntimeTransportMode = "trs_tx_power_rf_runtime_channel_noise_rx_rf_trs_rx";
        r.RuntimeStageWaveformsRequired = true;
        r.RuntimeStageWaveformsUsed = isfinite(double(sixgr.util.structGet( ...
            out, "RuntimeStageCount", NaN)));
        r.RuntimeSelfLoopWaveformsUsed = false;
        r.RuntimeChannelStateUsed = logical(sixgr.util.structGet(out, "RuntimeChannelStateUsed", false));
        r.RuntimeChannelLinkKeys = string(sixgr.util.structGet(out, "RuntimeChannelLinkKeys", ""));
        r.RuntimeNoiseApplied = logical(sixgr.util.structGet(out, "RuntimeNoiseApplied", false));
        r.RuntimeNoiseVarianceMean = double(sixgr.util.structGet(out, "RuntimeNoiseVarianceMean", NaN));
        r.RuntimeStageCount = double(sixgr.util.structGet(out, "RuntimeStageCount", NaN));
        if ~ok && strlength(strtrim(string(sixgr.util.structGet(out, "FailureReason", "")))) > 0
            r.FailureReason = string(sixgr.util.structGet(out, "FailureReason", ""));
        end
        if ok
            r.Status = "PASS";
        end
        r.Crash = logical(sixgr.util.structGet(out, "Crash", false));
        if r.Crash
            r.Status = "CRASH";
        end
        r.Notes = string(sixgr.util.structGet(out, "Notes", ""));
    catch ME
        r.Crash = true;
        r.CRCPass = NaN;
        r.Status = "CRASH";
        r.FailureReason = string(ME.identifier) + ": " + string(ME.message);
        r.Notes = string(ME.message);
    end
    rows(k) = r;
end
T = struct2table(rows, "AsArray", true);
end

function row = localMakeLinkTrialRow(cfg, direction, snr_dB, trialIdx)
seed0 = double(sixgr.util.structGet(cfg, "run.seed", 1));
dopp = double(sixgr.util.structGet(cfg, "channel.doppler_Hz", ...
    sixgr.util.structGet(cfg, "channel.dopplerHz", sixgr.util.structGet(cfg, "channel.fading.maxDoppler_Hz", 0))));
row = struct();
row.Direction = string(direction);
row.SNR_dB = double(snr_dB);
row.Seed = seed0 + double(trialIdx) - 1;
row.Frame = double(trialIdx);
row.Slot = double(trialIdx);
row.SSBIndex = NaN;
row.PBCHHypothesisSSBIndex = NaN;
row.SSBIdentityVerified = false;
row.SSBIndexSource = "";
row.BeamIndex = NaN;
row.SSBBurstConfiguredBeamCount = NaN;
row.SSBBurstExecutedBeamCount = NaN;
row.SSBBurstActiveIndices0Based = "";
row.SSBBurstPrecoderIDs = "";
row.SSBBurstPrecoderMatrixSHA256 = "";
row.SSBBurstPlanSHA256 = "";
row.SSBWaveformDomain = "";
row.SSBWaveformPorts = NaN;
row.SSBPhysicalTransmitAntennaElements = NaN;
row.SSBTxEvidenceSource = "";
row.MCS = NaN;
row.PRBs = NaN;
row.Layers = NaN;
row.Modulation = "";
    row.TargetCodeRate = NaN;
row.TBSize_bits = NaN;
row.PRBStart = NaN;
row.AllocatedPRBCount = NaN;
row.PRBCount = NaN;
row.SymbolStart = NaN;
row.NumSymbols = NaN;
if isempty(fieldnames(cfg)) && strlength(strtrim(string(direction))) == 0
    % Schema-only template row used by localEmptyLinkTrialTable.  It has no
    % channel claim; concrete profile resolution is required for every
    % actual DL/UL trial row below.
    row.ChannelModel = "";
else
    row.ChannelModel = localResolveRequestedLinkChannelModel(cfg);
end

row.ChannelModelApplied = "";
row.ChannelFadingApplied = false;
row.DopplerHz = dopp;
    row.CRCPass = NaN;
    row.CRCApplicable = false;
    row.CRCOutcome = "";
    row.BCHCrcPass = NaN;
    row.MIBDecoded = NaN;
    row.BCHTransportBlockNumBits = NaN;
    row.BCHTransportBlockHex = "";
    row.BCHTransportBlockHash = "";
    row.BCHScrambledBlockNumBits = NaN;
    row.BCHScrambledBlockHex = "";
    row.BCHScrambledBlockHash = "";
