    frameVals = double(T.Frame);
    slotVals = double(T.Slot);
    slotKeys = "frame_" + string(round(frameVals)) + "_slot_" + string(round(slotVals));
elseif all(ismember(["SFN","Slot"], vars))
    frameVals = double(T.SFN);
    slotVals = double(T.Slot);
